def test_payment_claim_fallback_uses_exact_validated_customer_wording() -> None:
    tool_results = [
        {
            "name": "answer_order_faq",
            "full_result": {
                "payment_policy": {
                    "source": "gulong_api_checkout_metadata",
                    "requested_payment_method": "credit card",
                    "requested_payment_name": (
                        "Straight Credit Card / Debit Card"
                    ),
                    "requested_payment_status": "ready",
                    "requested_payment_type_id": 7,
                    "requested_product_brand": "APOLLO",
                    "requested_brand_eligibility": "not_brand_restricted",
                    "payment_option": "Pay Now",
                }
            },
        },
        {
            "name": "search_promo_catalog",
            "full_result": {
                "status": "ok",
                "mode": "targeted",
                "evidence_ref": "promo_search:august",
                "requested_brands": ["Apollo"],
                "allowed_promo_refs": ["promo:apollo-3-1-promo"],
                "candidates": [
                    {
                        "promo_ref": "promo:apollo-3-1-promo",
                        "title": "APOLLO 3+1 PROMO",
                        "brands": ["APOLLO"],
                        "offer_summary": (
                            "Get one free tire for every purchase of three "
                            "eligible Apollo tires."
                        ),
                    },
                    {
                        "promo_ref": "promo:michelin-3-1-promo",
                        "title": "MICHELIN 3+1 PROMO",
                        "brands": ["MICHELIN"],
                        "offer_summary": "A different reviewed offer.",
                    },
                ],
            },
        },
    ]

    assert _unsupported_payment_claim_fallback_text(tool_results) == (
        "Yes po, puwede ang credit card for APOLLO under Pay Now. "
        "For the current APOLLO 3+1 PROMO, Get one free tire for every "
        "purchase of three eligible Apollo tires."
    )


def test_payment_fallback_preserves_only_authoritative_render_surfaces() -> None:
    units = _payment_fallback_response_units(
        [
            {
                "type": "text",
                "content": {"text": "Unsafe payment assertion."},
            },
            {
                "type": "render_surface",
                "content": {"surface_ref": "pres_product_abc"},
            },
            {
                "type": "image",
                "content": {
                    "image_ref": "untrusted_image",
                    "url": "https://example.com/not-authorized.jpg",
                },
            },
            {
                "type": "render_surface",
                "content": {"surface_ref": "pres_product_abc"},
            },
        ],
        "Validated payment fallback.",
    )

    assert units == [
        {
            "type": "text",
            "content": {"text": "Validated payment fallback."},
        },
        {
            "type": "render_surface",
            "content": {"surface_ref": "pres_product_abc"},
        },
    ]


def test_payment_fallback_without_surface_returns_only_safe_text() -> None:
    assert _payment_fallback_response_units(
        [{"type": "text", "content": {"text": "Unsafe."}}],
        "Safe response.",
    ) == [
        {"type": "text", "content": {"text": "Safe response."}}
    ]


def test_provider_grounded_payment_composition_requires_a_pure_typed_turn() -> None:
    payment_result = {
        "name": "answer_order_faq",
        "args": {"requested_payment_method": "Home Credit"},
        "full_result": {
            "payment_policy": {
                "source": "gulong_api_checkout_metadata",
                "requested_payment_method": "Home Credit",
                "requested_payment_status": "unsupported",
            }
        },
    }

    assert _provider_grounded_payment_response_text([payment_result]) == (
        "Wala pa po tayong Home Credit as a payment option."
    )
    assert (
        _provider_grounded_payment_response_text(
            [payment_result, {"name": "answer_policy_faq", "full_result": {}}]
        )
        == ""
    )


def test_location_contact_fallback_uses_structured_semantic_signal() -> None:
    signal = {
        "key": "location_response_status",
        "value": "unavailable_now",
        "source": "latest_user_message",
        "relation": "question_only",
    }
    lead = {
        "present": {"tire_size": "175/65R14", "tire_brand": "YOKOHAMA"}
    }

    assert _should_offer_location_contact_fallback(
        background_signals=[signal],
        lead_qualification=lead,
        selected_product_context=None,
        tool_results=[],
        interaction_packet=None,
        validated_choice_context=None,
    )


def test_location_response_status_is_closed_and_transient() -> None:
    signals = _construct_background_signals(
        candidates=[
            {
                "key": "location_response_status",
                "value": "not_sure_yet",
                "source": "latest_user_message",
                "confidence": "high",
                "relation": "question_only",
            },
            {
                "key": "location_response_status",
                "value": "Quezon City",
                "source": "customer_history",
                "confidence": "high",
                "relation": "asserted",
            },
        ],
        latest_product_observation={},
    )

    assert len(signals) == 1
    assert signals[0].key == "location_response_status"
    assert signals[0].value == "unavailable_now"
    assert signals[0].relation == "question_only"
    assert signals[0].safe_for_action is False


def test_location_contact_fallback_rejects_competing_or_satisfied_paths() -> None:
    signal = {
        "key": "location_response_status",
        "value": "unavailable_now",
        "source": "latest_user_message",
        "relation": "question_only",
    }
    base = {
        "background_signals": [signal],
        "selected_product_context": None,
        "interaction_packet": None,
        "validated_choice_context": None,
    }

    assert not _should_offer_location_contact_fallback(
        **base,
        lead_qualification={"present": {"tire_size": "175/65R14"}},
        tool_results=[],
    )
    assert not _should_offer_location_contact_fallback(
        **base,
        lead_qualification={
            "present": {
                "tire_size": "175/65R14",
                "tire_brand": "YOKOHAMA",
                "location": "Quezon City",
            }
        },
        tool_results=[],
    )
    assert not _should_offer_location_contact_fallback(
        **base,
        lead_qualification={
            "present": {"tire_size": "175/65R14", "tire_brand": "YOKOHAMA"}
        },
        tool_results=[{"name": "answer_policy_faq"}],
    )
    assert _should_offer_location_contact_fallback(
        **base,
        lead_qualification={
            "present": {"tire_size": "175/65R14", "tire_brand": "YOKOHAMA"}
        },
        tool_results=[{"name": "present_serviceable_location_choices"}],
    )


def test_location_unavailable_rejects_forced_location_picker_plan() -> None:
    rejection = _location_tool_plan_rejection(
        name="present_serviceable_location_choices",
        execution_args={},
        validated_choice_context={},
        background_signals=[
            {
                "key": "location_response_status",
                "value": "unavailable_now",
                "source": "latest_user_message",
                "relation": "question_only",
            }
        ],
        order_readiness={},
    )

    assert rejection["required_decision_layer"] == "contact_followup"
    assert rejection["source"] == "semantic_current_turn_location_response_status"


class MiniHTTPClient:
    def __init__(self):
        self.post_calls = []
        self.get_calls = []

    def post_json(self, path, *, params=None, json_data=None):
        self.post_calls.append({"path": path, "params": dict(params or {})})
        return _category_payload(
            [
                _raw_product(1, "atlas-r15", "ATLAS", "ATLAS 185/60/R15 FORCE HP 84H", "185", "60", "R15", 3000, tire_type="Budget"),
                _raw_product(
                    2,
                    "yokohama-r15",
                    "YOKOHAMA",
                    "YOKOHAMA 185/60/R15 BLUEARTH ES32 84H",
                    "185",
                    "60",
                    "R15",
                    4800,
                    tire_type="Mid Range",
                ),
                _raw_product(
                    3,
                    "michelin-r15",
                    "MICHELIN",
                    "MICHELIN 185/60/R15 ENERGY XM2+ 88H",
                    "185",
                    "60",
                    "R15",
                    6500,
                    tire_type="Premium",
                    installments=[{"bank_name": "BPI", "months_to_pay": 6, "percent_interest": 0}],
                ),
            ]
        )

    def get_json(self, path, params=None):
        self.get_calls.append(path)
        if path == "/car_tire_sizes":
            return [
                {"section_width": "185", "aspect_ratio": "60", "rim_size": "R15"},
                {"section_width": "175", "aspect_ratio": "65", "rim_size": "R14"},
            ]
        if path == "/promo_brands":
            return []
        return []


class ImageBackedMiniHTTPClient(MiniHTTPClient):
    def post_json(self, path, *, params=None, json_data=None):
        payload = super().post_json(
            path,
            params=params,
            json_data=json_data,
        )
        for category in payload:
            for product in category.get("products") or []:
                product["default_image"] = (
                    "https://gulongph.sgp1.digitaloceanspaces.com/"
                    f"product_images/{product['slug']}.webp"
                )
        return payload


