class FakeGeocoder:
    def geocode(self, address):
        text = str(address or "").lower()
        if "gilmore" in text:
            return {"lat": 14.6127, "lng": 121.0344}
        if "san juan" in text and "batangas" in text:
            return {"lat": 13.8270, "lng": 121.3960}
        if "san juan" in text:
            return {"lat": 14.6046, "lng": 121.0331}
        if "sm city fairview" in text:
            return {"lat": 14.7345991, "lng": 121.057901}
        if "general trias" in text or "gen tri" in text:
            return {"lat": 14.3215, "lng": 120.9073}
        if "makati" in text:
            return {"lat": 14.5665, "lng": 121.0296}
        return {}


