def _category_payload(products):
    grouped = {}
    for product in products:
        grouped.setdefault(product.get("tire_type") or "Premium", []).append(product)
    return [{"id": index + 1, "name": category, "products": rows} for index, (category, rows) in enumerate(grouped.items())]


