def _harness_with_single_product_observation():
    harness = _harness()
    harness.product_search({"rim_size": "R15", "top_k": 1})
    latest = harness.store.latest()
    assert latest is not None
    latest.product_cards = latest.product_cards[:1]
    latest.presented_products = latest.presented_products[:1]
    latest.best_products = latest.best_products[:1]
    latest.presentation_strategy["card_count"] = 1
    latest.presentation_strategy["brands"] = ["ATLAS"]
    latest.presentation_strategy["categories"] = ["Budget"]
    return harness


def _validated_slot_store(location: str = "General Trias"):
    service_tools = RuntimeV7ServiceTools(http_client=MiniServiceHTTPClient(), geocoder=FakeGeocoder())
    slots = service_tools.find_installation_slots(
        {
            "location": location,
            "service_type": "installation",
            "preferred_date": "today",
            "request_time": "2026-05-21 09:00:00",
            "top_k": 1,
            "slots_per_partner": 1,
        }
    )
    slot = slots["slot_groups"][0]["slots"][0]
    validation = service_tools.validate_installation_slot(
        {"observation_ref": slots["observation_ref"], "slot_ref": slot["slot_ref"]}
    )
    assert validation["status"] == "ok"
    return service_tools, slot


def _store_with_presented_product(product):
    store = ProductObservationStore()
    product = dict(product)
    item_ref = str(product.get("item_ref") or "prod_test")
    product.setdefault("item_ref", item_ref)
    card_ref = str(product.get("card_ref") or "card_test")
    store.save_search_result(
        {
            "observation_ref": "obs_test_product",
            "presentation_ref": "pres_test_product",
            "product_cards": [
                {
                    "card_ref": card_ref,
                    "item_ref": item_ref,
                    "product_id": product.get("product_id") or product.get("id"),
                    "slug": product.get("slug"),
                    "brand": product.get("brand") or product.get("make"),
                    "sku_model": product.get("sku_model") or product.get("model"),
                }
            ],
            "presented_products": [product],
            "best_products": [product],
        }
    )
    return store, card_ref, item_ref


