def _fixture_request_coverage(payload, response_units):
    """Build schema-valid coverage rows for structured composer test doubles."""

    plan = payload.get("customer_turn_plan") or {}
    rows = []
    for obligation in plan.get("request_obligations") or []:
        modes = set(obligation.get("required_response_modes") or [])
        authorized_refs = set(
            obligation.get("authorized_surface_refs") or []
        )
        indexes = []
        surface_refs = []
        for index, unit in enumerate(response_units):
            unit_type = str(unit.get("type") or "")
            content = unit.get("content") or {}
            surface_ref = str(content.get("surface_ref") or "")
            if "text" in modes and unit_type == "text" and not indexes:
                indexes.append(index)
            if (
                "surface" in modes
                and unit_type == "render_surface"
                and surface_ref in authorized_refs
            ):
                indexes.append(index)
                surface_refs.append(surface_ref)
        rows.append(
            {
                "obligation_id": obligation["obligation_id"],
                "disposition": obligation.get(
                    "expected_disposition", "answered"
                ),
                "response_unit_indexes": indexes,
                "surface_refs": surface_refs,
            }
        )
    return rows


class GroundingContractModel:
    """Model double spanning planning, tool retry, and final composition."""

    def __init__(
        self,
        *,
        payment_calls=None,
        forced_payment_call=None,
        skip_initial_tool=False,
        omit_delivery_lead_time=False,
    ):
        self.payment_calls = list(payment_calls or [])
        self.forced_payment_call = dict(forced_payment_call or {})
        self.skip_initial_tool = skip_initial_tool
        self.omit_delivery_lead_time = omit_delivery_lead_time
        self.main_calls = 0
        self.forced_tool_choices = []
        self.last_composer_payload = {}

    def complete(
        self,
        *,
        messages,
        tools,
        tool_choice="auto",
        response_format=None,
        max_tokens=None,
        temperature=None,
    ):
        del tools, max_tokens, temperature
        response_name = getattr(response_format, "__name__", "")
        if response_name == "RuntimeV7SemanticAnswerAuditModel":
            return {
                "content": json.dumps(
                    {
                        "decision": "supported",
                        "unsupported_claims": [],
                        "missing_answers": [],
                        "answer_goal_alignment": "aligned",
                        "customer_request_scope": "general_policy",
                        "case_specific_handling": "explicitly_pending",
                        "validation_process_handling": "none",
                    }
                ),
                "usage": {},
            }
        if response_name == "RuntimeV7FinalResponseModel":
            payload = json.loads(messages[-1]["content"])
            self.last_composer_payload = payload
            plan = payload.get("customer_turn_plan") or {}
            obligations = list(plan.get("request_obligations") or [])
            if not obligations:
                obligations = [
                    {
                        "obligation_id": (
                            str(item.get("evidence_ref") or "")
                            if str(item.get("evidence_ref") or "").startswith("faq:")
                            else f"faq:{item.get('faq_id')}"
                        )
                    }
                    for item in (
                        (plan.get("progression_context") or {}).get(
                            "required_faq_fact_answers"
                        )
                        or []
                    )
                    if item.get("answer_required")
                ]
            evidence_refs = [
                str(ref)
                for claim in payload.get("required_commercial_claims") or []
                for ref in claim.get("evidence_refs") or []
                if str(ref).strip()
            ]
            evidence_refs.extend(
                str(item.get("evidence_ref"))
                for item in (
                    (plan.get("progression_context") or {}).get(
                        "required_faq_fact_answers"
                    )
                    or []
                )
                if str(item.get("evidence_ref") or "").strip()
            )
            payment_turn = bool(self.payment_calls)
            text = (
                "Wala pa po tayong Home Credit. Available po ang Yokohama "
                "3-month 0% under Pay Later. Hindi po available ang Yokohama "
                "BPI 6-month 0% under Pay Later."
                if payment_turn
                else (
                    "May general delivery po through Greater Manila Area via "
                    "Lalamove. Hindi pa nito kino-confirm ang exact-address "
                    "serviceability."
                    if self.omit_delivery_lead_time
                    else
                    "May general delivery po through Greater Manila Area via "
                    "Lalamove, usually 7-10 days. Hindi pa nito kino-confirm "
                    "ang exact-address serviceability."
                )
            )
            return {
                "content": json.dumps(
                    {
                        "claim_assertions": [
                            {
                                "category": "payment_facts" if payment_turn else "faq_facts",
                                "response_unit_indexes": [0],
                                "evidence_refs": list(dict.fromkeys(evidence_refs)),
                            }
                        ],
                        "request_coverage": [
                            {
                                "obligation_id": item["obligation_id"],
                                "disposition": (
                                    item.get("expected_disposition")
                                    or "answered"
                                ),
                                "response_unit_indexes": [0],
                                "surface_refs": [],
                            }
                            for item in obligations
                        ],
                        "response_units": [
                            {"type": "text", "content": {"text": text}}
                        ],
                    }
                ),
                "tool_calls": [],
                "usage": {},
                "latency_ms": 1,
                "finish_reason": "stop",
            }

        self.main_calls += 1
        self.forced_tool_choices.append(tool_choice)
        if messages and messages[-1].get("role") == "tool":
            return {
                "content": "Grounded tool results are ready.",
                "tool_calls": [],
                "usage": {},
                "latency_ms": 1,
                "finish_reason": "stop",
            }
        if self.skip_initial_tool and self.main_calls == 1:
            return {
                "content": "Yes, we can deliver there.",
                "tool_calls": [],
                "usage": {},
                "latency_ms": 1,
                "finish_reason": "stop",
            }
        if self.payment_calls and self.main_calls == 1:
            return {
                "content": "",
                "tool_calls": self.payment_calls,
                "usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }
        forced_name = (
            (tool_choice.get("function") or {}).get("name")
            if isinstance(tool_choice, dict)
            else ""
        )
        if forced_name == "answer_order_faq":
            forced_payment_call = self.forced_payment_call or {
                "id": "call_missing_three_month",
                "name": "answer_order_faq",
                "args": {
                    "question": "Yokohama Pay Later 3-month 0%?",
                    "requested_payment_method": (
                        "3 months installment 0% interest"
                    ),
                    "requested_product_brand": "Yokohama",
                    "payment_option": "Pay Later",
                },
            }
            return {
                "content": "",
                "tool_calls": [forced_payment_call],
                "usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }
        if forced_name == "answer_policy_faq":
            return {
                "content": "",
                "tool_calls": [
                    {
                        "id": "call_delivery_policy",
                        "name": "answer_policy_faq",
                        "args": {"question": "Pwede delivery sa BGC?"},
                    }
                ],
                "usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }
        return {
            "content": "Grounded answer ready.",
            "tool_calls": [],
            "usage": {},
            "latency_ms": 1,
            "finish_reason": "stop",
        }


class FakeOrderHTTPClient:
    def __init__(self, *, order_details_response=None, submit_response=None):
        self.order_posts = []
        self.order_details_posts = []
        self.payment_posts = []
        self.order_details_response = order_details_response
        self.submit_response = submit_response

    def post_json(self, path, *, params=None, json_data=None):
        if path == "/order_details":
            self.order_details_posts.append({"path": path, "params": dict(params or {}), "json_data": json_data})
            if self.order_details_response is not None:
                return self.order_details_response
            return {
                "id": 35593,
                "customer_type_id": 11,
                "customer_source": None,
                "many_chat_id": "runtime-v7-test-35593",
                "date_created": "2026-05-29 17:16:18",
                "Status": "New",
                "payment_status": "Unpaid",
                "unpaid_order_status": None,
                "trans_type_id": 1,
                "payment_option": "CC-GP",
                "payment_type_id": 15,
                "payment_name": "Straight Credit Card / Debit Card",
                "branch_id": 329,
                "branch_name": "RAPIDE CENTURY CITY MALL",
                "branch_location": "Basement 2, Parking, Century City Mall, Kalayaan Ave. Makati City",
                "customer_name": "CARLO TEST",
                "phone_number": "09171234567",
                "total_qty": 1,
                "overall_total": 5035,
                "delivery_fee": 0,
                "item_orders": [
                    {
                        "id": 45217,
                        "orders_id": 35593,
                        "product_id": 486,
                        "sku": "YOKOHAMA 185/60/R15 BLUEARTH ES32 84H",
                        "slug": "yokohama-185-60-r15-bluearth-es32-84h",
                        "quantity": 1,
                        "price": 5135,
                        "srp": 6135,
                        "discount": 1000,
                        "total_discount": 1000,
                    }
                ],
                "add_ons": [],
            }
        if path == "/2c2p/payload":
            self.payment_posts.append({"path": path, "params": dict(params or {}), "json_data": json_data})
            return {"response": {"payment_url": "https://pgw-ui.2c2p.com/payment/runtime-v7-test"}}
        self.order_posts.append({"path": path, "params": dict(params or {}), "json_data": json_data})
        if self.submit_response is not None:
            return self.submit_response
        return {"status": "Success", "order_no": "SO-1", "data": {"order_id": "SO-1"}}


class FakeImageEvidenceModelClient:
    def __init__(self, content):
        self.contents = list(content) if isinstance(content, list) else [content]
        self.calls = []

    def extract_image_evidence(self, *, image_url, system_prompt, user_prompt, metadata=None):
        content = self.contents[min(len(self.calls), len(self.contents) - 1)]
        self.calls.append(
            {
                "image_url": image_url,
                "system_prompt": system_prompt,
                "user_prompt": user_prompt,
                "metadata": dict(metadata or {}),
            }
        )
        return {
            "content": content,
            "usage": {"prompt_tokens": 30, "completion_tokens": 20, "total_tokens": 50},
            "cache_usage": {},
            "latency_ms": 12,
            "finish_reason": "stop",
            "model": "gemini/gemini-2.5-flash",
        }


class FakeLiteLLMClient:
    def __init__(self):
        self.last_kwargs = {}
        self.last_embedding_kwargs = {}

    async def acompletion(self, **kwargs):
        self.last_kwargs = dict(kwargs)
        return {"choices": [{"message": {"content": '{"candidates":[]}'}, "finish_reason": "stop"}], "usage": {}}

    def embedding(self, **kwargs):
        self.last_embedding_kwargs = dict(kwargs)
        dimensions = int(kwargs.get("dimensions") or 3)
        return {"data": [{"embedding": [1.0] + [0.0] * max(0, dimensions - 1)}]}


class FakeFAQEmbeddingGateway:
    def embed(self, *, texts, model=None, metadata=None, dimensions=None):
        vectors = []
        for text in texts:
            lowered = str(text or "").lower()
            if (
                "pito" in lowered
                or "valve" in lowered
                or "what's included" in lowered
                or "free installation" in lowered
            ):
                vectors.append([1.0, 0.0, 0.0])
            elif "service locations" in lowered or "partner" in lowered or "branch" in lowered:
                vectors.append([0.0, 1.0, 0.0])
            else:
                vectors.append([0.0, 0.0, 1.0])
        return {"vectors": vectors, "model": model or "fake-embedding"}


