def test_location_uncertainty_turn_renders_contact_fallback_end_to_end() -> None:
    model = StaticPlainTextModel(
        "Sige po, saan po kayo located para ma-check ang installation?"
    )
    signal_model = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "location_response_status",
                        "value": "unavailable_now",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                    }
                ]
            }
        )
    )
    harness = RuntimeV7Harness(
        model_client=model,
        tools=_harness(),
        background_signal_model_client=signal_model,
    )
    harness.latest_selected_product_context = {
        "product_card_ref": "card_selected",
        "product_item_ref": "item_selected",
        "product_summary": {
            "brand": "YOKOHAMA",
            "tire_size": "175/65R14",
        },
    }

    turn = harness.run_turn(
        "Hindi pa ako sure sa city kung saan ipapakabit."
    )

    assert "contact number" in turn["runtime_final_response"].casefold()
    assert "saan po kayo located" not in turn["runtime_final_response"].casefold()
    assert any(
        event.get("type") == "location_contact_fallback_rendered"
        for event in turn["response_guard_events"]
    )


def test_location_uncertainty_suppresses_model_requested_location_picker() -> None:
    signal_model = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "location_response_status",
                        "value": "unavailable_now",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                    }
                ]
            }
        )
    )
    harness = RuntimeV7Harness(
        model_client=LocationChoiceThenTextModel(),
        tools=_harness(),
        background_signal_model_client=signal_model,
    )
    harness.latest_selected_product_context = {
        "product_card_ref": "card_selected",
        "product_item_ref": "item_selected",
        "product_summary": {
            "brand": "YOKOHAMA",
            "tire_size": "175/65R14",
        },
    }

    turn = harness.run_turn("Hindi pa ako sure sa city kung saan ipapakabit.")
    rendered = render_turn_for_channel(turn)

    assert "contact number" in turn["runtime_final_response"].casefold()
    assert turn["suppressed_channel_surface_tools"] == [
        "present_serviceable_location_choices"
    ]
    assert turn["location_choice_surface_status"]["reason"] == (
        "customer_location_unavailable_contact_fallback"
    )
    assert not any(item.get("type") == "cards" for item in rendered.content_messages)
    assert any(
        event.get("type") == "tool_plan_rejected"
        and event.get("required_decision_layer") == "contact_followup"
        for event in turn["tool_guard_events"]
    )




