class MultiLocationIntegratedContractModel:
    """Exercises wrong slot/location proposals through final composition."""

    def __init__(self):
        self.composer_calls = 0

    def complete(
        self,
        *,
        messages,
        tools,
        tool_choice="auto",
        response_format=None,
        max_tokens=None,
        temperature=None,
    ):
        del tools, tool_choice, max_tokens, temperature
        if response_format is not None:
            payload = json.loads(messages[-1]["content"])
            self.composer_calls += 1
            plan_payload = next(
                json.loads(message["content"])
                for message in reversed(messages)
                if message.get("role") == "user"
                and str(message.get("content") or "").lstrip().startswith("{")
                and "customer_turn_plan" in json.loads(message["content"])
            )
            plan = plan_payload["customer_turn_plan"]
            scope_map = (
                plan["progression_context"][
                    "authorized_service_area_claims_by_evidence_ref"
                ]
            )
            evidence_ref = next(iter(scope_map))
            scope = scope_map[evidence_ref][0]
            units = []
            assertions = []
            if self.composer_calls == 1:
                units.append(
                    {
                        "type": "text",
                        "content": {
                            "text": (
                                "May installation partners po sa Rosario, "
                                "Dasmarinas, Imus, at Bacoor."
                            )
                        },
                    }
                )
                assertions.append(
                    {
                        "category": "service_availability",
                        "response_unit_indexes": [0],
                        "evidence_refs": [evidence_ref],
                        "service_area_claims": [
                            {
                                "scope_ref": scope["scope_ref"],
                                "outcome": scope["outcome"],
                            }
                        ],
                    }
                )
            else:
                units.append(
                    {
                        "type": "text",
                        "content": {
                            "text": (
                                "Kung gusto ninyo, puwede nating i-check "
                                "nang hiwalay ang isa pang area."
                            )
                        },
                    }
                )
            units.extend(
                {
                    "type": "render_surface",
                    "content": {"surface_ref": row["surface_ref"]},
                }
                for row in plan_payload.get("presentation_surfaces") or []
                if row.get("surface_ref")
                and row["surface_ref"]
                in {
                    ref
                    for obligation in plan.get("request_obligations") or []
                    for ref in obligation.get("authorized_surface_refs") or []
                }
            )
            return {
                "content": json.dumps(
                    {
                        "claim_assertions": assertions,
                        "request_coverage": _fixture_request_coverage(
                            plan_payload,
                            units,
                        ),
                        "response_units": units,
                    }
                ),
                "tool_calls": [],
                "usage": {},
                "cache_usage": {},
                "latency_ms": 1,
                "finish_reason": "stop",
            }
        latest = messages[-1] if messages else {}
        if latest.get("role") == "tool":
            result = json.loads(str(latest.get("content") or "{}"))
            if (
                result.get("error_type") == "tool_plan_not_authorized"
                or result.get("outcome_type")
                == "deterministic_progression_redirect"
            ):
                return {
                    "content": "",
                    "tool_calls": [
                        {
                            "id": "call_partner_after_guard",
                            "name": "find_installation_partners",
                            "args": {
                                "location": "Bacoor City, Cavite",
                                "service_type": "installation",
                            },
                        }
                    ],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "tool_calls",
                }
            return {
                "content": "May service result na po.",
                "tool_calls": [],
                "usage": {},
                "cache_usage": {},
                "latency_ms": 1,
                "finish_reason": "stop",
            }
        return {
            "content": "",
            "tool_calls": [
                {
                    "id": "call_wrong_slot_first",
                    "name": "find_installation_slots",
                    "args": {
                        "location": "Bacoor City, Cavite",
                        "service_type": "installation",
                    },
                }
            ],
            "usage": {},
            "cache_usage": {},
            "latency_ms": 1,
            "finish_reason": "tool_calls",
        }


