class FailingBackgroundSignalModelClient:
    def __init__(self):
        self.call_count = 0

    def extract_background_signals(self, *, system_prompt, user_prompt, metadata=None):
        self.call_count += 1
        raise RuntimeError("model unavailable")


class SequencedBackgroundSignalModelClient:
    def __init__(self, contents):
        self.contents = list(contents)
        self.call_count = 0
        self.user_prompts = []

    def extract_background_signals(self, *, system_prompt, user_prompt, metadata=None):
        self.call_count += 1
        self.user_prompts.append(user_prompt)
        content = self.contents[min(self.call_count - 1, len(self.contents) - 1)]
        return {
            "content": content,
            "usage": {"prompt_tokens": 20, "completion_tokens": 10, "total_tokens": 30},
            "cache_usage": {},
            "latency_ms": 8,
            "finish_reason": "length" if content.endswith('"source":') else "stop",
            "model": "gemini/gemini-2.5-flash-lite",
        }


def test_product_search_harness_stores_observation_and_presented_products():
    harness = _harness()
    result = harness.product_search({"rim_size": "R15", "top_k": 1})

    assert result["observation_ref"].startswith("obs_product_search_")
    assert result["presentation_ref"].startswith("pres_product_search_")
    assert len(result["best_products"]) == 1
    assert len(result["product_cards"]) == 1
    assert len(result["presented_products"]) == 1
    assert all(card["observation_ref"] == result["observation_ref"] for card in result["product_cards"])
    compact = _compact_tool_result("product_search", result)
    assert any(card.get("warranty") for card in compact["product_card_headers"])
    assert any(card.get("tire_protection_plan") for card in compact["product_card_headers"])

    observation = harness.store.latest()
    assert observation is not None
    assert observation.observation_ref == result["observation_ref"]
    assert observation.presentation_ref == result["presentation_ref"]
    assert len(observation.presented_products) == 1


