def test_typed_brand_selection_plan_rejects_multiple_same_brand_skus():
    harness = _harness()
    search = harness.product_search({"rim_size": "R15", "top_k": 3})
    observation = harness.store.latest()
    assert observation is not None
    first_brand = observation.product_cards[0]["brand"]
    observation.product_cards[1]["brand"] = first_brand
    observation.product_cards[1]["sku_model"] = (
        f"{first_brand} SECOND DISTINCT MODEL"
    )

    resolution = harness.resolve_product_reference(
        {
            "reference_text": first_brand,
            "presentation_ref": search["presentation_ref"],
            "selection_basis": "brand",
            "interpreted_value": first_brand,
            "card_ref": observation.product_cards[0]["card_ref"],
        }
    )

    assert resolution["status"] == "ambiguous"
    assert len(resolution["candidates"]) == 2
    assert "exact visible SKU/model" in resolution["reason"]


def test_typed_brand_selection_plan_resolves_one_visible_brand_sku():
    harness = _harness()
    search = harness.product_search({"rim_size": "R15", "top_k": 3})
    observation = harness.store.latest()
    assert observation is not None
    selected = observation.product_cards[0]
    unique_brand = selected["brand"]
    for position, card in enumerate(observation.product_cards[1:], start=1):
        card["brand"] = f"OTHER BRAND {position}"

    resolution = harness.resolve_product_reference(
        {
            "reference_text": unique_brand,
            "presentation_ref": search["presentation_ref"],
            "selection_basis": "brand",
            "interpreted_value": unique_brand,
        }
    )

    assert resolution["status"] == "resolved"
    assert resolution["matched_by"] == "unique_visible_brand"
    assert resolution["card_ref"] == selected["card_ref"]


