def test_product_reference_tool_schemas_require_typed_selection_basis():
    schemas = {
        schema["function"]["name"]: schema["function"]["parameters"]
        for schema in PRODUCT_TOOL_SCHEMAS
    }

    for name in ("resolve_product_reference", "get_product_details"):
        assert schemas[name]["required"] == ["selection_basis"]
        assert set(
            schemas[name]["properties"]["selection_basis"]["enum"]
        ) == {
            "exact_ref",
            "ordinal",
            "brand",
            "model",
            "attribute",
        }


def test_final_composer_uses_one_progression_contract_without_stale_cta_rules():
    assert COMPLETE_TURN_COMPOSITION_PROMPT.strip() in FINAL_COMPOSER_SYSTEM_PROMPT
    combined_contract = " ".join(
        (
            COMPLETE_TURN_COMPOSITION_PROMPT
            + "\n"
            + CTA_POLICY_PROMPT
            + "\n"
            + PRODUCT_POLICY_PROMPT
        ).split()
    )
    for stale_rule in (
        "Omit the CTA only for a close",
        "ask if they want that prioritized",
        "guided priority question",
        "stable CTA",
    ):
        assert stale_rule not in combined_contract


def test_get_product_details_returns_stored_trusted_product_fields():
    harness = _harness()
    harness.product_search({"rim_size": "R15", "top_k": 3})
    observation = harness.store.latest()
    assert observation is not None
    observation.product_cards[2]["image_url"] = (
        "https://gulongph.sgp1.digitaloceanspaces.com/"
        "product_images/michelin-energy-xm2.webp"
    )

    details = harness.get_product_details({"card_ref": "card_3", "reference_text": "Michelin"})

    assert details["status"] == "ok"
    assert details["matched_by"] == "direct_ref"
    assert details["product"]["brand"] == "MICHELIN"
    assert details["product"]["installment_text"] == "BPI 6mo 0% interest"
    assert details["card"]["brand"] == "MICHELIN"
    assert details["card_runtime_insert"] is True
    assert details["selected_product_card"]["brand"] == "MICHELIN"
    assert details["selected_product_card"]["image_url"] == observation.product_cards[2]["image_url"]
    assert details["product"]["image_url"] == observation.product_cards[2]["image_url"]
    assert "Price:" in details["selected_product_card"]["card_text"]
    assert "Installment: BPI 6mo 0% interest" in details["selected_product_card"]["card_text"]
    assert "Warranty/TPP:" in details["selected_product_card"]["card_text"]
    assert "customer_price_line" in details["product"]
    assert "price" not in details["product"]
    assert "list_price" not in details["product"]
    assert "total_price" not in details["product"]
    compact = _compact_tool_result("get_product_details", details)
    assert compact["card_runtime_insert"] is True
    assert compact["selected_product_cards"][0]["customer_price_line"]
    assert "card_text" not in compact["selected_product_cards"][0]
    assert compact["presentation_units"][0]["unit_type"] == "selected_product_card"
    assert compact["presentation_units"][0]["runtime_renders_body"] is True
    assert "card_text" not in compact["presentation_units"][0]


