def test_unconfirmed_payment_inquiry_does_not_become_order_selection():
    harness = _harness()
    search = harness.product_search(
        {
            "section_width": "185",
            "aspect_ratio": "60",
            "rim_size": "R15",
            "top_k": 3,
        }
    )
    card = search["product_cards"][0]
    signals = [
        {
            "key": "service_type",
            "value": "installation",
            "status": "confirmed",
            "source": "latest_user_message",
        },
        {
            "key": "location",
            "value": "San Pedro, Laguna",
            "status": "confirmed",
            "source": "latest_user_message",
        },
        {
            "key": "payment_method",
            "value": "credit card installment",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
        {
            "key": "bank",
            "value": "BPI",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
        {
            "key": "installment_months",
            "value": "6",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
    ]

    readiness = build_order_readiness(
        current_user_message="Available ba BPI 6 months for this tire?",
        background_signals=signals,
        product_observation_store=harness.store,
        selected_product_context={
            "product_observation_ref": search["observation_ref"],
            "product_presentation_ref": search["presentation_ref"],
            "product_card_ref": card["card_ref"],
            "product_item_ref": card["item_ref"],
        },
    )
    summary = build_order_summary(
        payload={
            "product_observation_ref": search["observation_ref"],
            "product_presentation_ref": search["presentation_ref"],
            "product_card_ref": card["card_ref"],
            "product_item_ref": card["item_ref"],
        },
        current_user_message="Available ba BPI 6 months for this tire?",
        background_signals=signals,
        product_observation_store=harness.store,
        order_readiness=readiness.to_dict(),
    )

    assert "Payment option" not in readiness.collected
    assert "Payment method" not in readiness.collected
    assert "payment_option" not in summary["order_summary_snapshot"][
        "payment_selection"
    ]
    assert "payment_method" not in summary["order_summary_snapshot"][
        "payment_selection"
    ]
    runtime = RuntimeV7Harness(
        model_client=ScriptedRuntimeV7Model(),
        tools=harness,
    )
    proposed = runtime._drop_unconfirmed_payment_plan(
        {
            "payment_option": "Pay Now",
            "payment_method": "credit card installment",
            "bank": "BPI",
            "installment_months": 6,
        },
        signals,
    )
    assert "payment_option" not in proposed
    assert "payment_method" not in proposed
    assert "bank" not in proposed
    assert "installment_months" not in proposed
    ledger_signals = []
    for signal in signals:
        persisted = dict(signal)
        persisted["source"] = "signal_ledger"
        persisted["status"] = "remembered_signal"
        persisted["metadata"] = {
            "ledger": {
                "authority_source": signal["source"],
                "authority_status": signal["status"],
            }
        }
        ledger_signals.append(persisted)
    persisted_readiness = build_order_readiness(
        current_user_message="9:00 AM",
        background_signals=ledger_signals,
        product_observation_store=harness.store,
        selected_product_context={
            "product_observation_ref": search["observation_ref"],
            "product_presentation_ref": search["presentation_ref"],
            "product_card_ref": card["card_ref"],
            "product_item_ref": card["item_ref"],
        },
    )
    persisted_plan = runtime._drop_unconfirmed_payment_plan(
        {
            "payment_option": "Pay Now",
            "payment_method": "credit card installment",
            "bank": "BPI",
            "installment_months": 6,
        },
        ledger_signals,
    )
    assert "Payment option" not in persisted_readiness.collected
    assert "Payment method" not in persisted_readiness.collected
    assert "payment_option" not in persisted_plan
    assert "payment_method" not in persisted_plan


