def test_build_order_summary_renders_deterministic_body_from_trusted_refs():
    harness = _harness()
    service_tools = RuntimeV7ServiceTools(http_client=MiniServiceHTTPClient(), geocoder=FakeGeocoder())
    slots = service_tools.find_installation_slots(
        {
            "location": "General Trias",
            "service_type": "installation",
            "preferred_date": "today",
            "request_time": "2026-05-21 09:00:00",
            "top_k": 1,
            "slots_per_partner": 1,
        }
    )
    slot = slots["slot_groups"][0]["slots"][0]
    validation = service_tools.validate_installation_slot(
        {"observation_ref": slots["observation_ref"], "slot_ref": slot["slot_ref"]}
    )
    search = harness.product_search({"rim_size": "R15", "top_k": 1})
    card = search["product_cards"][0]

    summary = build_order_summary(
        payload={
            "summary_scope": "checkout",
            "product_presentation_ref": search["presentation_ref"],
            "product_card_ref": card["card_ref"],
            "product_item_ref": card["item_ref"],
            "quantity": 4,
            "service_type": "installation",
            "location": "Biñan, Laguna",
            "schedule": slot["start"],
            "contact_number": "09171234567",
            "customer_name": "Rico Santos",
            "email_address": "rico@example.com",
            "reservation_payment_method": "GCash",
            "balance_payment_method": "GCash",
        },
        current_user_message="sige proceed na",
        product_observation_store=harness.store,
        service_observation_store=service_tools.store,
        order_readiness={
            "status": "ready_for_summary",
            "customer_order_intent": "active",
            "can_prepare_order_summary": True,
            "collected": {
                "Installation area": "General Trias, Cavite",
            },
        },
    )

    assert validation["status"] == "ok"
    assert summary["status"] == "ready"
    assert summary["card_runtime_insert"] is True
    assert summary["can_submit_order"] is False
    assert summary["summary_preview"]["Name"] == "Rico Santos"
    assert summary["summary_preview"]["Contact No"] == "09171234567"
    assert summary["summary_preview"]["Service"] == "Installation"
    assert summary["summary_preview"]["Installation Area"] == (
        "General Trias, Cavite"
    )
    assert "Biñan, Laguna" not in summary["order_summary_block"]
    assert summary["missing_fields"] == []
    assert "🧾 Order Summary" in summary["order_summary_block"]
    assert "Product:" in summary["order_summary_block"]
    assert "Total: PHP" in summary["order_summary_block"]
    assert "Payment Option: Pay Later" in summary["order_summary_block"]
    assert "Reservation Payment Method: GCash" in summary["order_summary_block"]
    assert "Mode of Payment (for balance): GCash" in summary["order_summary_block"]
    assert "Email: rico@example.com" in summary["order_summary_block"]
    assert "Invoice to Company?: [YES/NO]" in summary["order_summary_block"]


