    assert broad["status"] == "ok"
    assert agent.latest_selected_product_context == {}

    narrowed = agent._execute_tool(
        "product_search",
        {
            "section_width": "185",
            "aspect_ratio": "60",
            "rim_size": "R15",
            "required_brands": ["ATLAS"],
            "top_k": 1,
        },
    )
    selected_card = narrowed["product_cards"][0]

    assert len(narrowed["product_cards"]) == 1
    assert selected_card["brand"] == "ATLAS"
    assert agent.latest_selected_product_context["product_presentation_ref"] == narrowed["presentation_ref"]
    assert agent.latest_selected_product_context["product_card_ref"] == selected_card["card_ref"]
    assert agent.latest_selected_product_context["product_item_ref"] == selected_card["item_ref"]


