@pytest.mark.parametrize(
    "location_text",
    [
        "Banda",
        "Service Areas",
        "Installation Locations",
        "Available Branches",
        "Partner Locations",
    ],
)
def test_find_installation_partners_rejects_generic_non_location_text(location_text):
    result = _service_tools().find_installation_partners(
        {"location": location_text, "service_type": "installation"}
    )
    compact = _compact_tool_result("find_installation_partners", result)

    assert result["status"] == "needs_location"
    assert result["query_basis"]["location_input_status"] == "generic_non_location"
    assert compact["query_basis"]["location_input_status"] == "generic_non_location"
    assert result["installation_partners"] == []
    assert "not a customer area" in result["note"]
    assert "present_serviceable_location_choices" in compact["note"]


def test_harness_guides_model_to_primary_location_surface_without_forced_tool_choice():
    signal_client = FakeBackgroundSignalModelClient(
        '{"candidates":[{"key":"location","value":"Service Areas",'
        '"source":"latest_user_message","confidence":"high",'
        '"relation":"question_only"},{"key":"service_type",'
        '"value":"installation","source":"latest_user_message",'
        '"confidence":"high"}]}'
    )
    agent = RuntimeV7Harness(
        model_client=PromptGuidedLocationSurfaceModel(),
        tools=_harness(),
        service_tools=_service_tools(),
        background_signal_model_client=signal_client,
        location_plan_executor=lambda args: {
            "status": "ok",
            "routing_only": True,
            "read_only": True,
            "location_choice_surface": {
                "presentation_ref": "location_choices:province:test",
                "source_version": "serviceable-locations-v1",
                "level": "province",
                "choices": [
                    {"label": "Metro Manila", "choice_ref": "loc_metro_manila"},
                    {"label": "Cavite", "choice_ref": "loc_cavite"},
                ],
            },
        },
        max_tool_rounds=3,
    )

    payload = agent.run_conversation(
        ["Gusto ko magpakabit pero wala pa akong city. Pakita service areas."]
    )
    first = payload["turns"][0]

    assert first["llm_calls"][0]["tool_choice"] == "auto"
    assert [result["name"] for result in first["tool_results"]] == [
        "present_serviceable_location_choices"
    ]
    assert not first.get("tool_routing_events")
    assert "Pili lang po kayo" in first["runtime_final_response"]


