def test_delivery_payment_policy_distinguishes_metro_manila_and_outside_cod():
    metro = delivery_payment_policy_for_location("Unit 1, Makati, Metro Manila")
    outside = delivery_payment_policy_for_location("Brgy Malagasang, Imus, Cavite")
    ambiguous_outside = delivery_payment_policy_for_location("San Juan, Batangas")

    assert metro["area_type"] == "metro_manila"
    assert metro["full_payment_required"] is True
    assert metro["cod_available"] is False
    assert outside["area_type"] == "outside_metro_manila"
    assert outside["cod_available"] is True
    assert outside["reservation_fee"] == 500.0
    assert ambiguous_outside["area_type"] == "outside_metro_manila"


