def test_order_faq_restores_explicit_term_from_question_when_model_only_passes_bank():
    class CurrentPaymentListProvider(
        FakeLiveInstallmentCheckoutMetadataProvider
    ):
        def checkout_metadata(self):
            metadata = super().checkout_metadata()
            for row in metadata["payment_types"]:
                if row.get("id") == 31:
                    row["available_brands"] = "MICHELIN, APOLLO"
                    row["updated_at"] = "2026-07-25T05:57:15.000000Z"
                    pay_later_row = dict(row)
                    pay_later_row["id"] = 26
                    pay_later_row["main_payment_type_id"] = 1
                    metadata["payment_types"].append(pay_later_row)
                    break
            return metadata

    result = answer_order_faq(
        {
            "question": (
                "Pwede ba BPI 6 months installment sa Yokohama "
                "kung Pay Later?"
            ),
            "requested_payment_method": "BPI",
            "requested_product_brand": "Yokohama",
            "payment_option": "Pay Later",
        },
        canonical_values_provider=CurrentPaymentListProvider(),
    )

    policy = result["payment_policy"]
    assert policy["requested_payment_status"] == "ready"
    assert policy["requested_payment_type_id"] == 26
    assert policy["requested_payment_type_updated_at"] == (
        "2026-07-25T05:57:15.000000Z"
    )
    assert policy["requested_brand_eligibility"] == "not_eligible"
    assert policy["payment_option"] == "Pay Later / Pay After Service"
    assert result["answer"] == (
        "Yokohama is not currently eligible for "
        "BPI Credit Card Installment 6 months 0%."
    )


