def test_final_composer_sees_checkout_validation_facts_not_prescriptions():
    plan = resolve_checkout_plan(
        selected_product={"product_id": 1, "brand": "ATLAS"},
        quantity=2,
        service_path="installation",
        location="General Trias",
        service_location={
            "service_location_ref": "svc_test",
            "name": "Test Partner",
            "service_types": ["installation"],
            "order_value_threshold": 12000,
        },
        schedule="2026-06-03 16:00",
        has_validated_slot=True,
        quote_breakdown={"installation_threshold_total": 8000.0},
        payment_selection=resolve_payment_selection(payment_option="Pay Later", payment_method="GCash"),
    )

    composer_results = _final_composer_tool_results(
        [
            {
                "round": 1,
                "name": "build_order_payload",
                "args": {},
                "result": {
                    "status": "needs_clarification",
                    "checkout_plan": plan,
                    "invalid_fields": [
                        {
                            "field": "trusted_order_total",
                            "value": "8000.0",
                            "reason": "Selected installation partner requires at least PHP 12,000.00 order value.",
                        }
                    ],
                },
            }
        ]
    )

    result = composer_results[0]["result"]
    result_text = json.dumps(result, ensure_ascii=False)
    assert "checkout_plan" not in result
    assert "prescriptions" not in result_text
    assert result["checkout_validation"]["status"] == "blocked"
    assert result["checkout_validation"]["blocking_issues"][0]["field"] == "trusted_order_total"
    assert "Offer delivery" not in result_text


