def test_build_order_payload_requires_validated_installation_slot_before_submit_ready():
    harness = _harness()
    service_tools = _service_tools()
    search = harness.product_search({"rim_size": "R15", "top_k": 1})
    card = search["product_cards"][0]
    slots = service_tools.find_installation_slots(
        {
            "location": "Makati",
            "service_type": "installation",
            "preferred_date": "2026-05-21",
            "request_time": "2026-05-21 09:00:00",
        }
    )
    group = slots["slot_groups"][0]
    slot = group["slots"][0]
    partner = group
    schedule = f"{slot['date']} {slot['time_text']}"
    base_payload = {
        "product_presentation_ref": search["presentation_ref"],
        "product_card_ref": card["card_ref"],
        "product_item_ref": card["item_ref"],
        "quantity": 5,
        "service_type": "installation",
        "location": "Makati",
        "service_location_ref": partner["service_location_ref"],
        "schedule": schedule,
        "contact_number": "09171234567",
        "customer_name": "Rico Santos",
        "email_address": "rico@example.com",
        "payment_option": "Pay Later",
        "reservation_payment_method": "GCash",
    }

    unvalidated = build_order_payload(
        payload=base_payload,
        current_user_message="submit order",
        product_observation_store=harness.store,
        service_observation_store=service_tools.store,
        canonical_values_provider=FakeCheckoutMetadataProvider(),
    )

    assert unvalidated["status"] == "needs_clarification"
    assert unvalidated["can_submit_order"] is False
    assert any(item["field"] == "schedule" for item in unvalidated["invalid_fields"])
    assert unvalidated["order_payload"] == {}

    validation = service_tools.validate_installation_slot(
        {"observation_ref": slots["observation_ref"], "slot_ref": slot["slot_ref"]}
    )
    payload_without_partner_ref = dict(base_payload)
    payload_without_partner_ref.pop("service_location_ref")
    validated = build_order_payload(
        payload=payload_without_partner_ref,
        current_user_message="submit order",
        product_observation_store=harness.store,
        service_observation_store=service_tools.store,
        canonical_values_provider=FakeCheckoutMetadataProvider(),
    )

    assert validation["status"] == "ok"
    assert validated["status"] == "ready"
    assert validated["can_submit_order"] is True
    assert validated["invalid_fields"] == []
    assert validated["order_payload"]["data"]["transaction_type"] == 10
    assert validated["order_payload"]["data"]["selectedBranch"]["branch_id"] == str(partner["branch_id"])

    month_names = {
        "01": "January",
        "02": "February",
        "03": "March",
        "04": "April",
        "05": "May",
        "06": "June",
        "07": "July",
        "08": "August",
        "09": "September",
        "10": "October",
        "11": "November",
        "12": "December",
    }
    _, month, day = slot["date"].split("-")
    compact_time = slot["time_text"].replace(":00 ", "").lower()
    human_schedule_payload = dict(payload_without_partner_ref)
    human_schedule_payload["schedule"] = f"{month_names[month]} {int(day)} {compact_time}"
    validated_from_human_schedule = build_order_payload(
        payload=human_schedule_payload,
        current_user_message="summary is correct, proceed and send payment link",
        product_observation_store=harness.store,
        service_observation_store=service_tools.store,
        canonical_values_provider=FakeCheckoutMetadataProvider(),
    )

    assert validated_from_human_schedule["status"] == "ready"
    assert validated_from_human_schedule["invalid_fields"] == []
    assert validated_from_human_schedule["order_payload"]["data"]["delivery_date"] == slot["date"]
    assert validated_from_human_schedule["order_payload"]["data"]["delivery_time"].endswith(":00")


