def test_match_payment_proof_matches_latest_request_but_does_not_verify_paid():
    payment_request = {
        "payment_request_ref": "payment_request_test",
        "order_id": "35593",
        "order_payload_ref": "order_payload_test",
        "payment_stage": "full_payment",
        "expected_amount": 5035.0,
        "payment_option": "Pay Now",
        "payment_method": "GCash",
    }
    evidence_refs = [
        {
            "evidence_ref": "img_payment_1",
            "image_type": "payment_proof",
            "analysis": {
                "type": "payment_proof",
                "amount": "PHP 5,035.00",
                "reference_no": "GCASH-123",
                "payment_method": "GCash",
                "paid_at": "2026-05-29 17:30:00",
                "confidence": 0.95,
            },
        }
    ]
    http = FakeOrderHTTPClient()

    result = match_payment_proof(
        payload={"payment_request_ref": "payment_request_test"},
        external_evidence_refs=evidence_refs,
        payment_request_store={"payment_request_test": payment_request},
        order_payload_store={},
        http_client=http,
    )

    assert result["status"] == "matched_unverified"
    assert result["payment_proof_received"] is True
    assert result["amount_match"] is True
    assert result["expected_amount_text"] == "PHP 5,035.00"
    assert result["extracted_amount_text"] == "PHP 5,035.00"
    assert result["reference_no"] == "GCASH-123"
    assert result["backend_payment_status"] == "Unpaid"
    assert "paid" not in " ".join(result["customer_explanation_hints"]).lower()
    assert http.order_details_posts[0]["json_data"] == {"order_id": "35593"}


def test_payment_request_surface_is_inserted_by_runtime_renderer():
    payment_result = {
        "status": "ok",
        "payment_request_ref": "payment_request_abc",
        "presentation_ref": "pres_payment_request_abc",
        "payment_instruction_block": (
            "Payment Request for Order SO-1\n"
            "Amount Due: PHP 12,040.00 (full payment)\n"
            "Primary Payment QR:\n"
            "https://storage.googleapis.com/gulong_chatbot_files/images/gulong_qr.png\n"
            "Alternative Account Details:\n"
            "BPI Bank Transfer\n"
            "Account Name: Golden Point Auto Care Inc.\n"
            "Account Number: 9671002072"
        ),
    }
    tool_results = [
        {
            "name": "prepare_payment_request",
            "result": _compact_tool_result("prepare_payment_request", payment_result),
            "full_result": payment_result,
        }
    ]
    model_text = json.dumps(
        {
            "response_units": [
                {"type": "text", "content": {"text": "Ito po yung payment request."}},
                {"type": "render_surface", "content": {"surface_ref": "pres_payment_request_abc"}},
                {"type": "text", "content": {"text": "After payment, send niyo lang po yung screenshot for verification."}},
            ]
        }
    )

    response = _compose_runtime_final_response(model_text, tool_results)

    assert response.startswith("Ito po yung payment request.")
