def test_order_readiness_retains_explicit_summary_quantity_but_not_an_assumed_default():
    harness = _harness_with_single_product_observation()
    latest = harness.store.latest()
    card = latest.product_cards[0]
    refs = {
        "product_presentation_ref": latest.presentation_ref,
        "product_card_ref": card["card_ref"],
        "product_item_ref": card["item_ref"],
    }
    explicit = build_order_summary(
        payload={**refs, "quantity": 2, "service_type": "delivery", "delivery_address": "Marikina"},
        current_user_message="2 pcs deliver sa Marikina",
        product_observation_store=harness.store,
    )
    retained = build_order_readiness(
        current_user_message="GCash",
        background_signals=[
            {
                "key": "payment_method",
                "value": "GCash",
                "source": "latest_user_message",
                "relation": "selected",
            }
        ],
        product_observation_store=harness.store,
        selected_product_context=refs,
        previous_order_summary_snapshot=explicit["order_summary_snapshot"],
    )
    defaulted = build_order_summary(
        payload={**refs, "service_type": "delivery", "delivery_address": "Marikina"},
        current_user_message="deliver sa Marikina",
        product_observation_store=harness.store,
    )
    still_defaulted = build_order_readiness(
        current_user_message="GCash",
        background_signals=[],
        product_observation_store=harness.store,
        selected_product_context=refs,
        previous_order_summary_snapshot=defaulted["order_summary_snapshot"],
    )

    assert retained.collected["Quantity"] == "2 tires"
    assert not any("defaults to 4" in item for item in retained.assumptions)
    assert defaulted["order_summary_snapshot"]["quantity_defaulted"] is True
    assert defaulted["order_summary_snapshot"]["quantity_source"] == "assumed_default"
    assert still_defaulted.collected["Quantity"] == "4 tires (assumed default)"


