def test_corrected_relation_replaces_prior_value_and_remains_durable():
    model = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "payment_option",
                        "value": "Pay Later",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "corrected",
                        "evidence": "Pay Later pala",
                    }
                ]
            }
        )
    )

    context = build_commercial_state_context(
        current_user_message="Pay Later pala, hindi Pay Now.",
        previous_background_signals=[
            {
                "key": "payment_option",
                "value": "Pay Now",
                "status": "remembered_signal",
                "confidence": "high",
                "source": "signal_ledger",
                "relation": "selected",
            }
        ],
        model_client=model,
    )

    payment = next(
        signal
        for signal in context["background_signals"]
        if signal["key"] == "payment_option"
    )
    assert payment["value"] == "Pay Later"
    assert payment["relation"] == "corrected"

    ledger = InMemoryBackgroundSignalLedgerStore()
    ledger.save("corrected", context["background_signals"], turn_index=2)
    persisted = ledger.load("corrected")
    assert persisted[0]["relation"] == "corrected"
    assert persisted[0]["metadata"]["ledger"]["authority_relation"] == "corrected"


