def test_selected_relation_preserves_existing_durable_choice_behavior():
    model = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "payment_option",
                        "value": "Pay Now",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "selected",
                        "evidence": "Pay Now po",
                    }
                ]
            }
        )
    )

    context = build_commercial_state_context(
        current_user_message="Pay Now po.",
        model_client=model,
    )
    payment = context["background_signals"][0]
    assert payment["status"] != "mentioned_unconfirmed"
    assert payment["relation"] == "selected"

    ledger = InMemoryBackgroundSignalLedgerStore()
    ledger.save("selected", context["background_signals"], turn_index=1)
    assert ledger.load("selected")[0]["value"] == "Pay Now"
    assert "Unknown providers must still be emitted" in BACKGROUND_SIGNAL_EXTRACTOR_SYSTEM_PROMPT
    assert "named only to scope a payment" in BACKGROUND_SIGNAL_EXTRACTOR_SYSTEM_PROMPT
    assert "is not a product-search preference" in BACKGROUND_SIGNAL_EXTRACTOR_SYSTEM_PROMPT
    assert "immediately preceding assistant turn" in BACKGROUND_SIGNAL_EXTRACTOR_SYSTEM_PROMPT
    assert "relation=selected" in BACKGROUND_SIGNAL_EXTRACTOR_SYSTEM_PROMPT
    assert "does not need extra words like" in BACKGROUND_SIGNAL_EXTRACTOR_SYSTEM_PROMPT


