def test_model_contract_hides_generic_requires_validation_from_model_context():
    context = build_runtime_v7_context(
        current_user_message="Ito yung screenshot https://cdn.example.com/tire.jpg",
        background_signals=[
            {
                "key": "tire_size",
                "value": "175/65R14",
                "status": "external_evidence_unvalidated",
                "confidence": "high",
                "source": "external_evidence",
                "safe_for_action": False,
                "requires_validation": True,
            }
        ],
        external_evidence_refs=[
            {
                "evidence_ref": "img_test_1",
                "source": "customer_image",
                "media_type": "image",
                "status": "extracted_unvalidated",
                "safe_for_action": False,
                "requires_validation": True,
                "summary": "tire image with visible size",
            }
        ],
        capability_profile={"selected_domains": ["product"]},
    )

    assert "requires_validation=" not in context
    assert "external_evidence_unvalidated" in context
    assert "extracted_unvalidated" in context
    assert "safe_for_action=" not in context
    system_prompt = build_runtime_v7_system_prompt(["product"])
    assert "combines a question about a visible card detail with a new search/filter request" in system_prompt
    assert "answer the visible-card question first" in system_prompt
    assert "Do not map reservation_payment_method or balance_payment_method" in system_prompt
    assert "Do not proactively offer installment just because a payment signal exists" in system_prompt
    assert "product-installment compatibility question alone" in ORDER_POLICY_PROMPT
    assert "product-specific details win" in ORDER_POLICY_PROMPT
    assert "needs_payment_clarification" in ORDER_POLICY_PROMPT
    assert "COD means the remaining balance on delivery" in ORDER_POLICY_PROMPT
    assert "provides those details, call build_order_summary" in ORDER_POLICY_PROMPT
    assert "recommended_next_tool=build_order_payload" in ORDER_POLICY_PROMPT
    normalized_order_policy = " ".join(ORDER_POLICY_PROMPT.split())
    assert "earliest actual afternoon slot" in normalized_order_policy
    assert "12:00 PM` fallback" in normalized_order_policy
    assert "preference-only and cannot build a payload" in normalized_order_policy
    assert "base price per tire plus the total for the requested" in PRODUCT_POLICY_PROMPT
    assert "product-card\nquantity total already includes" in ORDER_POLICY_PROMPT
    assert "do not subtract the same promo again" in " ".join(ORDER_POLICY_PROMPT.lower().split())
    assert "not final order payment selection" in " ".join(ORDER_POLICY_PROMPT.split())
    assert "asks for product discovery, alternatives, comparison" in system_prompt
    assert "future-looking promise when the matching product tool is available" in system_prompt
    assert "call a product tool before claiming that options" in system_prompt
    assert "ask for the tire size" in system_prompt
    assert "Treat brief price inquiries" in system_prompt
    assert "ask for the tire size directly" in system_prompt
    assert "para saan po yan" in system_prompt
    assert "brand-specific pricelist" in system_prompt
    assert "Broad inquiry wording" in system_prompt
    assert "fewer than five total brands" in system_prompt
    assert "product_search cannot validate vehicle fitment" in system_prompt
    assert "customer confirms the tire size" in system_prompt
    assert "answering product, promo, price" in system_prompt
    assert "If the fitment tool returns no" in system_prompt
    assert "Partial clues such as rim 15" in system_prompt
    assert "extract_compatible_fitment returns candidate sizes only" in system_prompt
    assert "quantity plus budget" in system_prompt
    assert "set budget_scope=total" in system_prompt
    service_prompt = build_runtime_v7_system_prompt(["service"])
    service_prompt_compact = " ".join(service_prompt.split())
    assert "Once the customer has chosen or accepted delivery" in service_prompt
    assert "Delivery does not require an installation schedule" in service_prompt_compact
    installment_banks_schema = next(
        field
        for field in PRODUCT_TOOL_SCHEMAS[0]["function"]["parameters"]["properties"]
        if field == "installment_banks"
    )
    assert "Product installment bank filter only" in PRODUCT_TOOL_SCHEMAS[0]["function"]["parameters"]["properties"][installment_banks_schema]["description"]
    assert "Do not use for vehicle fitment phrases" in PRODUCT_TOOL_SCHEMAS[0]["function"]["parameters"]["properties"]["semantic_query"]["description"]
    assert "Use total when the customer gives a budget with quantity" in PRODUCT_TOOL_SCHEMAS[0]["function"]["parameters"]["properties"]["budget_scope"]["description"]
    summary_schema = next(schema for schema in ORDER_TOOL_SCHEMAS if schema["function"]["name"] == "build_order_summary")
    assert summary_schema["function"]["parameters"]["properties"]["summary_scope"]["enum"] == ["preview", "checkout", None]
    assert summary_schema["function"]["parameters"]["properties"]["presentation_intent"]["enum"] == ["show", "update_only", None]
    summary_props = summary_schema["function"]["parameters"]["properties"]
    assert "product installment compatibility" in summary_props["payment_option"]["description"]
    quote_schema = next(schema for schema in ORDER_TOOL_SCHEMAS if schema["function"]["name"] == "calculate_order_quote")
    assert "disputes of promo math" in quote_schema["function"]["description"]
    assert "Do not fill from product installment interest" in summary_props["payment_method"]["description"]


