def test_image_evidence_flows_to_context_signals_and_memory_refs():
    payload = {
        "type": "tire",
        "tire_sizes": ["185/60 R15"],
        "tire_brand": "BRIDGESTONE",
        "tire_model": "ECOPIA EP150",
        "evidence_text": "185/60R15 84H",
        "confidence": 0.92,
    }
    image_client = FakeImageEvidenceModelClient(json.dumps(payload))
    harness = RuntimeV7Harness(
        model_client=BucketDiscoveryProductModel(),
        tools=_harness(),
        image_evidence_extractor=ImageEvidenceExtractor(model_client=image_client),
    )

    record = harness.run_turn("hm po ito size ko https://cdn.example.com/uploads/tire.jpg")

    refs = record["image_evidence"]["external_evidence_refs"]
    assert refs[0]["status"] == "extracted_unvalidated"
    assert refs[0]["safe_for_action"] is False
    assert "tire_size=185/60R15" in refs[0]["extracted_fields"]
    signals = {signal["key"]: signal for signal in record["background_signals_before_turn"]}
    assert signals["external_product_evidence"]["source"] == "external_evidence"
    assert signals["external_product_evidence"]["requires_validation"] is True
    assert signals["tire_size"]["value"] == "185/60R15"
    assert signals["tire_size"]["source"] == "external_evidence"
    assert signals["tire_size"]["status"] == "external_evidence_unvalidated"
    assert signals["tire_size"]["safe_for_action"] is False
    assert "## External Evidence" in record["context_input"]
    assert refs[0]["evidence_ref"] in record["context_input"]
    assert refs[0]["evidence_ref"] in record["active_working_memory_after_turn"]["text"]
    assert image_client.calls[0]["metadata"]["component"] == "runtime_v7_image_evidence"
    intake = record["preturn_intake"]
    assert intake["mode"] == "joined_async_preturn_intake"
    assert intake["parallelized"] is True
    assert intake["fire_and_forget"] is False
    assert intake["joined_before_model_context"] is True
    assert "image_evidence" in intake["stages"]


