def test_human_agent_history_hydrates_context_signals_and_memory():
    background_client = FakeBackgroundSignalModelClient(
        '{"candidates":['
        '{"key":"tire_size","value":"205/55R16","source":"human_agent_history","confidence":"high","status_hint":"human_agent_provided"},'
        '{"key":"preferred_brands","value":["APOLLO","MICHELIN"],"source":"human_agent_history","confidence":"medium","status_hint":"human_agent_provided"}'
        "]}",
    )
    harness = RuntimeV7Harness(
        model_client=BucketDiscoveryProductModel(),
        tools=_harness(),
        background_signal_model_client=background_client,
        conversation_history=[
            {
                "role": "agent",
                "sender": "Sarah",
                "text_content": "Customer needs 205/55R16. Prefer Apollo or Michelin.",
                "message_id": "agent_20555r16",
                "datetime": "2026-05-21T09:01:00",
            }
        ],
    )

    record = harness.run_turn("hm po")

    assert "human_agent_history" in background_client.user_prompt
    assert "Customer needs 205/55R16" in record["context_input"]
    assert "trusted_for_context=true" in record["context_input"]
    signals = {signal["key"]: signal for signal in record["background_signals_before_turn"]}
    assert signals["tire_size"]["value"] == "205/55R16"
    assert signals["tire_size"]["source"] == "human_agent_history"
    assert signals["tire_size"]["status"] == "human_agent_context"
    assert signals["tire_size"]["safe_for_action"] is False
    assert "205/55R16" in record["active_working_memory_after_turn"]["text"]
    assert record["conversation_evidence"]["external_evidence_refs"][0]["evidence_ref"] in record["active_working_memory_after_turn"]["text"]


