def test_runtime_hydrates_product_search_bare_rim_from_commercial_size_signal():
    class BareRimCommercialProductModel:
        def complete(self, *, messages, tools, tool_choice="auto", response_format=None):
            if messages[-1].get("role") == "tool":
                return {
                    "content": "May product options po.",
                    "tool_calls": [],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "stop",
                }
            return {
                "content": "",
                "tool_calls": [
                    {
                        "id": "call_product_search_commercial",
                        "name": "product_search",
                        "args": {
                            "section_width": "195",
                            "rim_size": "14",
                            "required_brands": ["Apollo"],
                            "quantity": 4,
                        },
                    }
                ],
                "usage": {},
                "cache_usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }

    background_client = FakeBackgroundSignalModelClient(
        '{"candidates":['
        '{"key":"tire_size","value":"195R14C","source":"human_agent_history","confidence":"high","status_hint":"human_agent_provided"},'
        '{"key":"preferred_brands","value":["APOLLO"],"source":"latest_user_message","confidence":"high","status_hint":"confirmed"}'
        "]}",
    )
    harness = RuntimeV7Harness(
        model_client=BareRimCommercialProductModel(),
        tools=_harness(),
        background_signal_model_client=background_client,
    )

    record = harness.run_turn("Apollo po magkano kung 4 pcs?")

    tool_result = record["tool_results"][0]
    assert tool_result["model_args"]["rim_size"] == "14"
    assert tool_result["args"]["rim_size"] == "R14C"


