    assert SERVICE_POLICY_PROMPT not in product_context
    assert ORDER_POLICY_PROMPT not in product_context
    assert ORDER_READINESS_POLICY_PROMPT not in product_context
    assert "Conversation Progression Policy" not in product_context
    assert SERVICE_POLICY_PROMPT not in service_context
    assert PRODUCT_POLICY_PROMPT not in service_context
    assert ORDER_POLICY_PROMPT not in service_context
    assert ORDER_POLICY_PROMPT not in order_context
    assert PRODUCT_POLICY_PROMPT not in order_context
    assert SERVICE_POLICY_PROMPT not in order_context
    assert PRODUCT_POLICY_PROMPT not in mixed_context
    assert SERVICE_POLICY_PROMPT not in mixed_context
    assert ORDER_POLICY_PROMPT not in mixed_context


