def test_compact_product_tool_result_does_not_expose_response_strategy():
    harness = _harness()
    search = harness.product_search({"rim_size": "R15", "top_k": 3})
    buckets = harness.discover_brand_buckets({"rim_size": "R15", "top_brands_per_bucket": 2})
    search_compact = _compact_tool_result("product_search", search)
    bucket_compact = _compact_tool_result("discover_brand_buckets", buckets)

    # Direct full runner results can keep diagnostics, but model-facing compact
    # tool messages should avoid response-strategy instructions.
