def test_commercial_state_context_tracks_lead_and_order_readiness():
    client = FakeBackgroundSignalModelClient(
        '{"candidates":['
        '{"key":"tire_size","value":"175 65 14","source":"latest_user_message","confidence":"high","confirmation_state":"confirmed"},'
        '{"key":"location","value":"Cubao","source":"customer_history","confidence":"medium","status_hint":"mentioned"},'
        '{"key":"quantity","value":"4 tires","source":"customer_history","confidence":"medium","status_hint":"mentioned"},'
        '{"key":"car_make_model","value":"Toyota Wigo","source":"customer_history","confidence":"medium","status_hint":"mentioned"},'
        '{"key":"budget","value":"PHP 15,000 max for 4 tires","source":"customer_history","confidence":"medium","status_hint":"mentioned"}'
        "]}",
    )
    state_context = build_commercial_state_context(
        current_user_message="Boss confirmed na tire size ko 175 65 14. Patingin budget options.",
        active_working_memory=(
            "Customer is from Cubao and prefers budget tires for their Toyota Wigo "
            "worth around PHP 15,000 max for 4 tires."
        ),
        recent_turns=[
            {
                "role": "user",
                "content": "Taga-Cubao ako, Wigo, 4 tires at around 15k total budget.",
            }
        ],
        model_client=client,
    )

    signals = {signal["key"]: signal for signal in state_context["background_signals"]}
    assert signals["tire_size"]["value"] == "175/65R14"
    assert signals["tire_size"]["status"] == "confirmed_by_latest_user_message"
    assert signals["tire_size"]["safe_for_action"] is True
    assert signals["location"]["value"] == "Cubao"
    assert signals["location"]["source"] == "customer_history"
    assert signals["quantity"]["value"] == "4"
    assert signals["car_make_model"]["value"] == "Toyota Wigo"

    missing_info = state_context["missing_info"]
    assert "product_search" not in missing_info
    assert missing_info["lead_qualification"]["status"] == "incomplete"
    assert missing_info["lead_qualification"]["missing"] == ["tire_brand"]
    assert missing_info["order_readiness"]["status"] == "not_ready"
    assert "specific_sku_model" not in missing_info["order_readiness"]["missing"]
    assert "chosen_schedule_slot" in missing_info["order_readiness"]["missing"]
    assert "branch_addons" not in missing_info["order_readiness"]["missing"]
    assert "branch_addons" in missing_info["order_readiness"]["optional"]
    assert "only readiness gate" in missing_info["order_readiness"]["note"]
    assert "still evaluating products" in missing_info["order_readiness"]["note"]
    assert signals["location"]["ask_timing"] == "later_for_fulfillment_reuse_known_value"


