def test_background_location_signals_use_shared_location_resolver():
    resolver = RuntimeV7LocationResolver(http_client=MiniServiceHTTPClient(), api_key="")
    cases = [
        ("pque", "Paranaque City, Metro Manila", "Paranaque City", "Metro Manila", None),
        ("gen tri", "General Trias, Cavite", "General Trias", "Cavite", None),
        ("bukdinon", "Bukidnon", None, "Bukidnon", None),
        ("SM Fairview", "SM City Fairview, Quezon City, Metro Manila", "Quezon City", "Metro Manila", "SM City Fairview"),
    ]

    for raw, expected_value, expected_city, expected_province, expected_landmark in cases:
        client = FakeBackgroundSignalModelClient(
            '{"candidates":['
            f'{{"key":"location","value":"{raw}","source":"latest_user_message","confidence":"high","status_hint":"mentioned"}}'
            "]}",
        )
        state_context = build_commercial_state_context(
            current_user_message=f"installation near {raw}",
            model_client=client,
            location_resolver=resolver,
        )

        signal = {item["key"]: item for item in state_context["background_signals"]}["location"]
        resolution = signal["resolution"]
        assert signal["value"] == expected_value
        assert resolution["status"] == "resolved_location"
        assert resolution["display_label"] == expected_value
        assert resolution["city_hint"] == expected_city
        assert resolution["province_hint"] == expected_province
        assert resolution["landmark_hint"] == expected_landmark
        assert resolution["requires_tool_validation"] is True
        assert signal["safe_for_action"] is False
        context = build_runtime_v7_context(
            current_user_message=f"installation near {raw}",
            background_signals=state_context["background_signals"],
            missing_info=state_context["missing_info"],
        )
        assert f"display_label={expected_value}" in context


