    assert "location: Pateros, Metro Manila | status=remembered_signal | source=signal_ledger | requires_validation=true" not in context
    assert "## Service Lookup Context" in context
    assert "partner lookup ready: service_type=installation; location=Pateros, Metro Manila" in context
    assert "Use find_installation_partners for the first read-only nearby partner check" in context


