def test_model_primary_background_signals_use_model_candidates_and_deterministic_canonicalization():
    client = FakeBackgroundSignalModelClient(
        '{"candidates":['
        '{"key":"tire_size","value":"175 65 14","source":"latest_user_message","confidence":"high","status_hint":"confirmed"},'
        '{"key":"quantity","value":"4 pcs","source":"latest_user_message","confidence":"high","status_hint":"mentioned"},'
        '{"key":"budget","value":"15k max","source":"latest_user_message","confidence":"high","status_hint":"mentioned"},'
        '{"key":"brand","value":"michelan","source":"latest_user_message","confidence":"high","status_hint":"mentioned"},'
        '{"key":"brand","value":"yoko","source":"latest_user_message","confidence":"medium","status_hint":"alternative preferred brand"},'
        '{"key":"location","value":"qc","source":"latest_user_message","confidence":"medium","status_hint":"mentioned"},'
        '{"key":"reservation_payment_method","value":"GCash","source":"latest_user_message","confidence":"medium"},'
        '{"key":"balance_payment_method","value":"credit card installment","source":"latest_user_message","confidence":"medium"}'
        "]}"
    )
    state_context = build_commercial_state_context(
        current_user_message=(
            "Boss 175 65 14 confirmed. michelan sana or yoko ok din, QC ako. "
            "4 pcs, 15k max. GCash reservation then card installment sa balance."
        ),
        active_working_memory="Customer prefers budget tires for a Toyota Wigo.",
        model_client=client,
    )

    signals = {signal["key"]: signal for signal in state_context["background_signals"]}
    assert signals["tire_size"]["value"] == "175/65R14"
    assert signals["preferred_brands"]["value"] == "MICHELIN, YOKOHAMA"
    assert signals["preferred_brands"]["source"] == "latest_user_message"
    assert signals["location"]["value"] == "Quezon City"
    assert signals["quantity"]["value"] == "4"
    assert signals["budget"]["value"] == "about PHP 15,000 total"
    assert signals["reservation_payment_method"]["value"] == "gcash"
    assert signals["balance_payment_method"]["value"] == "credit card installment"
    assert signals["reservation_payment_method"]["ask_timing"] == "later_after_product_and_fulfillment"
    assert signals["balance_payment_method"]["ask_timing"] == "later_after_product_and_fulfillment"
    assert state_context["missing_info"]["lead_qualification"]["present"]["tire_brand"] == "MICHELIN, YOKOHAMA"
    assert state_context["missing_info"]["order_readiness"]["present"]["reservation_payment_method"] == "gcash"
    assert state_context["missing_info"]["order_readiness"]["present"]["balance_payment_method"] == "credit card installment"
    assert state_context["background_signal_extraction"]["mode"] == "model_primary"
    assert state_context["background_signal_extraction"]["model_used"] is True
    assert state_context["background_signal_extraction"]["candidate_source"] == "model_primary_with_structured_context"
    assert state_context["background_signal_extraction"]["model_candidate_count"] == 8
    assert client.call_count == 1
    assert state_context["background_signal_extraction"]["diagnostics"]["raw_message_extraction"] == "disabled"
    assert "extraction_diagnostics" in client.user_prompt
    assert "fallback_extraction_diagnostics" not in client.user_prompt
    assert "canonical_examples" in client.user_prompt
    assert '"locations"' not in client.user_prompt
    assert '"installation_partners"' not in client.user_prompt


