def test_background_signal_prompt_keeps_narrative_memory_context_only():
    client = FakeBackgroundSignalModelClient('{"candidates":[]}')

    build_commercial_state_context(
        current_user_message="May mas pangmatagalan ba diyan?",
        active_working_memory=(
            "The confirmed tire size is 185/55R16, quantity is 4 tires, "
            "and the budget is around PHP 18,000 total."
        ),
        model_client=client,
    )

    assert "use active_working_memory only to understand the conversation" in client.system_prompt
    assert "return at most 8 candidates" in client.system_prompt
    assert "Deduplicate repeated facts by key and value" in client.system_prompt
    assert "Never turn it into a candidate fact" in client.system_prompt
    assert "Do not extract facts from active_working_memory under any status" in client.system_prompt
    assert "Do not output warranty_years" in client.system_prompt
    assert '"hm" or "hm po" means how much' in client.system_prompt
    assert '"wgo" usually means Toyota Wigo' in client.system_prompt
    assert "The confirmed tire size is 185/55R16" in client.user_prompt


