def test_llm_usage_aggregation_distinguishes_metered_and_unmetered_retries():
    summary = _aggregate_llm_usage(
        [
            {
                "provider_call_count": 2,
                "metered_provider_call_count": 2,
                "usage_summary": {
                    "prompt_tokens": 40,
                    "completion_tokens": 20,
                    "total_tokens": 60,
                },
            },
            {
                "provider_call_count": 2,
                "usage_summary": {
                    "prompt_tokens": 20,
                    "completion_tokens": 10,
                    "total_tokens": 30,
                },
            },
        ]
    )

    assert summary["llm_call_count"] == 4
    assert summary["logical_llm_call_count"] == 2
    assert summary["metered_llm_call_count"] == 3
    assert summary["missing_usage_call_count"] == 1
    assert summary["unmetered_retry_count"] == 1
    assert summary["total_tokens"] == 90

    exception_only = _aggregate_llm_usage(
        [
            {
                "provider_call_count": 3,
                "metered_provider_call_count": 0,
                "usage_summary": {},
            }
        ]
    )
    assert exception_only["missing_usage_call_count"] == 3
    assert exception_only["unmetered_retry_count"] == 2


