def test_background_signal_extractor_uses_pydantic_response_contract():
    payload = {
        "candidates": [
            {
                "key": "excluded_tire_categories",
                "value": "Premium",
                "source": "latest_user_message",
                "confidence": "high",
                "status_hint": "excluded",
                "evidence": "hindi premium",
            }
        ]
    }

    validator = getattr(BackgroundSignalExtractionResponseModel, "model_validate", None)
    parsed = validator(payload) if callable(validator) else BackgroundSignalExtractionResponseModel.parse_obj(payload)

    assert parsed.candidates[0].key == "excluded_tire_categories"
    assert _is_valid_candidate_payload({"content": '{"candidates":[]}'}) is True
    assert _is_valid_candidate_payload({"content": '{"not_candidates":[]}'}) is False
    assert (
        _is_valid_candidate_payload(
            {"content": '{"candidates":[{"key":"tire_size","value":{},"source":"latest_user_message"}]}'}
        )
        is False
    )


