def test_runtime_v7_gateway_retries_transient_transport_error_once():
    class Retry503LiteLLMClient(FakeLiteLLMClient):
        def __init__(self):
            super().__init__()
            self.calls = []

        async def acompletion(self, **kwargs):
            self.calls.append(dict(kwargs))
            if len(self.calls) == 1:
                raise RuntimeError('{"code": 503, "status": "UNAVAILABLE"}')
            return await super().acompletion(**kwargs)

    client = Retry503LiteLLMClient()
    gateway = RuntimeV7LLMGateway(
        config=RuntimeV7LLMGatewayConfig(
            model="gemini/gemini-2.5-flash-lite",
            api_key_env="MISSING_KEY",
            max_transport_retries=1,
            transport_retry_backoff_s=0,
        ),
        client=client,
    )

    response = gateway.complete(messages=[{"role": "user", "content": "compose"}])

    assert len(client.calls) == 2
    assert response["request_debug"]["transport_attempt_count"] == 2
    assert response["transport_retry_events"][0]["event"] == "LLM_TRANSIENT_TRANSPORT_RETRY"


def test_runtime_v7_gateway_does_not_retry_non_transient_error():
    class InvalidRequestLiteLLMClient(FakeLiteLLMClient):
        def __init__(self):
            super().__init__()
            self.calls = []

        async def acompletion(self, **kwargs):
            self.calls.append(dict(kwargs))
            raise RuntimeError("400 invalid response schema")

    client = InvalidRequestLiteLLMClient()
    gateway = RuntimeV7LLMGateway(
        config=RuntimeV7LLMGatewayConfig(
            model="gemini/gemini-2.5-flash-lite",
            api_key_env="MISSING_KEY",
            max_transport_retries=1,
            transport_retry_backoff_s=0,
        ),
        client=client,
    )

    with pytest.raises(RuntimeError, match="invalid response schema"):
        gateway.complete(messages=[{"role": "user", "content": "compose"}])

    assert len(client.calls) == 1


