def test_runtime_harness_preserves_thought_signature_tool_call_ids_by_default():
    model = ThoughtSignatureToolModel()
    agent = RuntimeV7Harness(model_client=model, tools=_harness(), thought_signature_mode="preserve")

    turn = agent.run_turn("185/60R15 options")
    second_call_messages = model.calls[1]
    assistant_tool_message = next(message for message in second_call_messages if message.get("role") == "assistant" and message.get("tool_calls"))
    tool_message = next(message for message in second_call_messages if message.get("role") == "tool")

    assert "__thought__" in assistant_tool_message["tool_calls"][0]["id"]
    assert "__thought__" in tool_message["tool_call_id"]
    assert turn["thought_signature_mode"] == "preserve"
    assert "thought_signature_events" not in turn


def test_runtime_harness_can_strip_thought_signature_tool_call_ids_for_ab_probe():
    model = ThoughtSignatureToolModel()
    agent = RuntimeV7Harness(model_client=model, tools=_harness(), thought_signature_mode="strip")

    turn = agent.run_turn("185/60R15 options")
    second_call_messages = model.calls[1]
    assistant_tool_message = next(message for message in second_call_messages if message.get("role") == "assistant" and message.get("tool_calls"))
    tool_message = next(message for message in second_call_messages if message.get("role") == "tool")

    assert assistant_tool_message["tool_calls"][0]["id"] == "call_product"
    assert tool_message["tool_call_id"] == "call_product"
    assert turn["thought_signature_mode"] == "strip"
    assert turn["thought_signature_events"] == [
        {
            "round": 1,
            "type": "thought_signature_stripped",
            "tool_call_index": 0,
            "tool_name": "product_search",
            "stripped_tool_call_id": "call_product",
            "signature_length": 6,
        }
    ]


