def test_runtime_v7_gateway_retries_without_context_cache_on_gemini_cached_content_conflict():
    class RetryOnceLiteLLMClient(FakeLiteLLMClient):
        def __init__(self):
            super().__init__()
            self.calls = []

        async def acompletion(self, **kwargs):
            self.calls.append(dict(kwargs))
            self.last_kwargs = dict(kwargs)
            if len(self.calls) == 1:
                raise RuntimeError(
                    "CachedContent can not be used with GenerateContent request setting "
                    "system_instruction, tools or tool_config."
                )
            return {
                "choices": [{"message": {"content": '{"candidates":[]}'}, "finish_reason": "stop"}],
                "usage": {},
            }

    client = RetryOnceLiteLLMClient()
    gateway = RuntimeV7LLMGateway(
        config=RuntimeV7LLMGatewayConfig(
            model="gemini/gemini-2.5-flash",
            api_key_env="MISSING_KEY",
            enable_context_cache=True,
        ),
        client=client,
    )

    response = gateway.complete(
        messages=[
            {"role": "system", "content": "stable prompt " * 900},
            {"role": "user", "content": "search"},
        ],
        tools=[
            {
                "type": "function",
                "function": {
                    "name": "product_search",
                    "description": "Search product catalog.",
                    "parameters": {"type": "object", "properties": {}},
                },
            }
        ],
    )

    assert len(client.calls) == 2
    assert client.calls[0]["messages"][0]["content"][0]["cache_control"]["type"] == "ephemeral"
    assert "tool_choice" not in client.calls[0]
    assert isinstance(client.calls[1]["messages"][0]["content"], str)
    assert client.calls[1]["tool_choice"] == "auto"
    assert response["request_cache"]["enabled"] is False
    assert response["request_cache"]["retry_of_cache_enabled_request"] is True
    assert response["request_cache"]["tool_schemas_in_cache_scope"] is False
    assert response["cache_guard_events"][0]["event"] == "GEMINI_CONTEXT_CACHE_RETRY_WITHOUT_CACHE"
    assert response["cache_guard_events"][0]["provider_mode"] == "google_ai_studio_gemini"


def test_runtime_v7_gateway_does_not_retry_context_cache_for_unrelated_error():
    class FailingLiteLLMClient(FakeLiteLLMClient):
        def __init__(self):
            super().__init__()
            self.calls = []

        async def acompletion(self, **kwargs):
            self.calls.append(dict(kwargs))
            raise RuntimeError("transient upstream failure")

    client = FailingLiteLLMClient()
    gateway = RuntimeV7LLMGateway(
        config=RuntimeV7LLMGatewayConfig(
            model="gemini/gemini-2.5-flash",
            api_key_env="MISSING_KEY",
            enable_context_cache=True,
        ),
        client=client,
    )

    with pytest.raises(RuntimeError, match="transient upstream failure"):
        gateway.complete(
            messages=[
                {"role": "system", "content": "stable prompt " * 900},
                {"role": "user", "content": "search"},
            ],
            tools=[
                {
                    "type": "function",
                    "function": {
                        "name": "product_search",
                        "description": "Search product catalog.",
                        "parameters": {"type": "object", "properties": {}},
                    },
                }
            ],
        )

    assert len(client.calls) == 1


