def test_product_tool_schemas_include_promo_types_and_reference_tools():
    tool_names = {schema["function"]["name"] for schema in PRODUCT_TOOL_SCHEMAS}
    assert {
        "product_search",
        "discover_brand_buckets",
        "extract_compatible_fitment",
        "resolve_product_reference",
        "get_product_details",
        "answer_product_faq",
    }.issubset(tool_names)
    all_tool_names = {schema["function"]["name"] for schema in ALL_RUNTIME_V7_TOOL_SCHEMAS}
    assert {
        "answer_service_faq",
        "find_installation_partners",
        "find_installation_slots",
        "answer_order_faq",
    }.issubset(all_tool_names)
    assert {schema["function"]["name"] for schema in ORDER_TOOL_SCHEMAS} == {
        "answer_order_faq",
        "calculate_order_quote",
        "build_order_summary",
        "build_order_payload",
        "submit_order",
        "prepare_payment_request",
        "match_payment_proof",
        "get_order_details",
    }
    product_search_schema = next(schema for schema in PRODUCT_TOOL_SCHEMAS if schema["function"]["name"] == "product_search")
    assert "Do not use for broad no-preference or size-only inquiries" in product_search_schema["function"]["description"]
    assert "promo_types" in product_search_schema["function"]["parameters"]["properties"]
    assert "required_brands" in product_search_schema["function"]["parameters"]["properties"]
    assert "brand_match_mode" in product_search_schema["function"]["parameters"]["properties"]
    assert product_search_schema["function"]["parameters"]["properties"]["brand_match_mode"]["enum"] == ["prefer", "strict"]
    rim_size_description = product_search_schema["function"]["parameters"]["properties"]["rim_size"]["description"]
    assert "265/35ZR21" in rim_size_description
    assert "ZR21" in rim_size_description
    assert "Do not drop ZR/C suffixes" in rim_size_description
    required_brand_description = product_search_schema["function"]["parameters"]["properties"]["required_brands"]["description"]
    assert "image/OCR alone" in required_brand_description
    assert "May Yokohama 185/65R15" in required_brand_description
    assert "Michelin or Yokohama 175/65R14 meron" in required_brand_description
    assert "brands" not in product_search_schema["function"]["parameters"]["properties"]
    assert "preferred_brands" in product_search_schema["function"]["parameters"]["properties"]
    preferred_brand_description = product_search_schema["function"]["parameters"]["properties"]["preferred_brands"]["description"]
    assert "image/OCR-visible brands" in preferred_brand_description
    assert "Do not use this instead of required_brands" in preferred_brand_description
    assert "excluded_brands" in product_search_schema["function"]["parameters"]["properties"]
    assert "excluded_origins" in product_search_schema["function"]["parameters"]["properties"]
    assert "excluded_tire_categories" in product_search_schema["function"]["parameters"]["properties"]
    assert "budget 15k" in product_search_schema["function"]["parameters"]["properties"]["tire_categories"]["description"]
    assert "first/yung una/card one are product refs" in product_search_schema["function"]["parameters"]["properties"]["quantity"]["description"]
    assert "selected visible option has installment" in product_search_schema["function"]["parameters"]["properties"]["installment_only"]["description"]
    assert "ply_rating" in product_search_schema["function"]["parameters"]["properties"]
    bucket_schema = next(schema for schema in PRODUCT_TOOL_SCHEMAS if schema["function"]["name"] == "discover_brand_buckets")
    assert "brand/category/price-tier narrowing" in bucket_schema["function"]["description"]
    bucket_props = bucket_schema["function"]["parameters"]["properties"]
    assert "budget_max" in bucket_props
    assert "budget_scope" in bucket_props
    assert "required_brands" in bucket_props
    assert "excluded_tire_categories" in bucket_props
    assert "top_brands_per_bucket" in bucket_props
    fitment_schema = next(schema for schema in PRODUCT_TOOL_SCHEMAS if schema["function"]["name"] == "extract_compatible_fitment")
    assert "vehicle_query" in fitment_schema["function"]["parameters"]["properties"]
    assert {"section_width", "aspect_ratio", "rim_size", "tire_size_clue", "soft_preferences"}.issubset(
        fitment_schema["function"]["parameters"]["properties"]
    )
    assert "customer's tire sidewall" in fitment_schema["function"]["description"]
    service_schema_names = {schema["function"]["name"] for schema in SERVICE_TOOL_SCHEMAS}
    assert service_schema_names == {
        "answer_service_faq",
        "find_installation_partners",
        "get_branch_addons",
        "find_installation_slots",
        "validate_installation_slot",
    }
    partner_schema = next(schema for schema in SERVICE_TOOL_SCHEMAS if schema["function"]["name"] == "find_installation_partners")
    slot_schema = next(schema for schema in SERVICE_TOOL_SCHEMAS if schema["function"]["name"] == "find_installation_slots")
    assert "installation partner coverage" in partner_schema["function"]["description"]
    assert "selected/visible product setup is ready for slot discovery" in partner_schema["function"]["description"]
    assert "use find_installation_slots instead" in partner_schema["function"]["description"]
    assert "nearby/malapit" in slot_schema["function"]["description"]
    assert "visible/selected product plus known customer area" in slot_schema["function"]["description"]


