def test_answer_policy_faq_routes_free_delivery_to_order_fee_policy():
    answer = answer_policy_faq(
        {
            "question": "Kung online kayo free deliver nyo yung gulong within QC area?",
            "customer_context": "Visible products: ARIVO Budget, WESTLAKE Budget",
            "service_type": "delivery",
        }
    )

    assert answer["status"] == "ok"
    assert answer["matched_domain"] == "order"
    assert answer["policy_type"] == "delivery_fee"
    assert answer["requires_context"] == ["selected_product_or_category"]
    assert "Budget" in answer["answer_basis"]
    assert answer["policy_facts"]["paid_delivery_fee_php"] == 500
    assert answer["context_policy_application"]["matched_categories"] == ["Budget"]
    assert answer["context_policy_application"]["delivery_fee_php"] == 500
    assert "applicable fee" in answer["composition_hint"]
    compact = _compact_tool_result("answer_policy_faq", answer)
    compact_text = json.dumps(compact, ensure_ascii=False)
    assert compact["answer"] is None
    assert compact["answer_basis"] is None
    assert compact["policy_facts"]["paid_delivery_fee_php"] == 500
    assert compact["context_policy_application"]["delivery_fee_php"] == 500
    assert "FREE: Apollo" not in compact_text


