def test_required_faq_fact_contract_accepts_paraphrase_and_flags_omission():
    plan = {
        "progression_context": {
            "required_faq_fact_answers": [
                {
                    "evidence_ref": "faq:order:delivery",
                    "required_answer_facts": [
                        {
                            "fact_id": "greater_manila_delivery_path",
                            "canonical_text": "Greater Manila Area: Lalamove",
                            "all_terms": [
                                "greater",
                                "manila",
                                "area",
                                "lalamove",
                            ],
                        },
                        {
                            "fact_id": "delivery_lead_time",
                            "canonical_text": "Estimated delivery time: 7-10 days",
                            "regex": (
                                r"\b7\s*(?:-|to|hanggang)\s*10\s*"
                                r"(?:days?|araw)\b"
                            ),
                        },
                    ],
                }
            ]
        }
    }
    complete = [
        {
            "type": "text",
            "content": {
                "text": (
                    "Greater Manila Area deliveries use Lalamove and usually "
                    "take 7 to 10 araw."
                )
            },
        }
    ]
    missing_time = [
        {
            "type": "text",
            "content": {"text": "Greater Manila Area deliveries use Lalamove."},
        }
    ]

    assert _final_composer_required_faq_fact_contract_violations(
        complete,
        customer_turn_plan=plan,
    ) == []
    violations = _final_composer_required_faq_fact_contract_violations(
        missing_time,
        customer_turn_plan=plan,
    )
    assert [item["fact_id"] for item in violations] == [
        "delivery_lead_time"
    ]


def test_answer_service_faq_uses_hybrid_retrieval():
    answer = answer_service_faq(
        {"question": "pito at balancing included?"},
        embedding_gateway=FakeFAQEmbeddingGateway(),
    )

    assert answer["status"] == "ok"
    assert answer["domain"] == "service"
    assert answer["faq_id"] == "service_what_s_included_when_i_purchase_tires_from_gulong_ph"
    assert answer["matched_by"] in {"lexical", "vector", "hybrid_vector"}
    assert "Mounting" in answer["answer"]
    assert "Tire Valves" in answer["answer"]


def test_answer_service_faq_covers_nitrogen_as_addon_not_run_flat():
    answer = answer_service_faq({"question": "Nitrogen po yata un"})

    assert answer["status"] == "ok"
    assert answer["domain"] == "service"
    assert answer["faq_id"] == "service_do_you_offer_nitrogen_inflation"
    assert "regular compressed air" in answer["answer"]
    assert "does not make the tire puncture-proof, no-flat, or run-flat" in answer["answer"]
    assert "add-on service" in answer["answer"]


def test_answer_product_faq_explains_run_flat_without_claiming_specific_sku_feature():
    answer = answer_product_faq(
        {
            "question": "no flat na po ba ito type ng tire?",
            "customer_context": "Dunlop Grandtrek AT25 visible product card",
        }
    )

    assert answer["status"] == "ok"
    assert answer["domain"] == "product"
    assert answer["faq_id"] == "product_what_are_run_flat_tires"
    assert "limited distance" in answer["answer"]
    assert "Regular tires are not run-flat unless" in answer["answer"]
    assert "Nitrogen inflation is different" in answer["answer"]


def test_answer_product_faq_does_not_answer_nitrogen_from_unrelated_warranty_docs():
    answer = answer_product_faq({"question": "may nitrogen po ba?"})

    assert answer["status"] == "no_match"
    assert answer["domain"] == "product"
    assert answer["reason"] == "question asks about nitrogen service/add-on, not product FAQ"


def test_context_instructs_model_how_to_use_faq_tool_results():
    context = build_runtime_v7_context(
        current_user_message="May warranty ba?",
        capability_profile={
            "selected_domains": ["product"],
            "faq_hints": [
                {
                    "faq_id": "product_do_your_tires_have_a_warranty",
                    "domain": "product",
                    "suggested_tool": "answer_product_faq",
                    "title": "Do your tires have a warranty?",
                    "question": "Do your tires have a warranty?",
                }
            ],
        },
    )

    assert "## FAQ Tool Hints" in context
    assert "## FAQ Tool Results" not in context
    compact = _compact_tool_result("answer_product_faq", answer_product_faq({"question": "May warranty ba?"}))
    assert compact["source_type"] == "faq"
    assert "specific query" in compact["composition_guidance"]
    assert "do not simply restate" in compact["composition_guidance"]
    assert "Do not mention retrieval, embeddings, RAG, corpus, or internal tool details" in compact["composition_guidance"]


def test_context_tool_objectives_prevent_faq_from_ending_mixed_fitment_turn():
    context = build_runtime_v7_context(
        current_user_message="may installment ba? need ko gulong pang vios",
        background_signals=[
            {
                "key": "car_make_model",
                "value": "Vios",
                "status": "mentioned_unconfirmed",
                "source": "latest_user_message",
            }
        ],
        capability_profile={
            "candidate_tools": ["extract_compatible_fitment", "answer_order_faq"],
            "selected_domains": ["order", "product"],
            "exposed_tools": ["extract_compatible_fitment", "answer_order_faq"],
            "matched_signal_keys": {"extract_compatible_fitment": ["car_make_model"]},
            "faq_hints": [
                {
                    "faq_id": "order_do_you_offer_installment_payments",
                    "domain": "order",
                    "suggested_tool": "answer_order_faq",
                    "title": "Do you offer installment payments?",
                    "question": "Do you offer installment payments?",
                }
            ],
        },
    )

    assert "## Tool Objectives" in context
    assert "tool=extract_compatible_fitment" in context
    assert "tool=answer_order_faq" in context
    assert "do not stop after the FAQ/tool result" in context


