def test_live_pack_marks_only_customer_visible_product_cards_as_delivered():
    store = ProductObservationStore()
    store.save_search_result(
        {
            "observation_ref": "obs_synthetic_delivery",
            "presentation_ref": "pres_synthetic_delivery",
            "product_cards": [
                {
                    "card_ref": "card_1",
                    "item_ref": "prod_1",
                    "brand": "ARIVO",
                    "sku_model": "ARIVO 195/55/R16 PREMIO COMFORT 6",
                },
                {
                    "card_ref": "card_2",
                    "item_ref": "prod_2",
                    "brand": "MICHELIN",
                    "sku_model": "MICHELIN 195/55/R16 PRIMACY 3 ZP 91V",
                },
            ],
        }
    )
    harness = SimpleNamespace(
        turn_records=[
            {
                "runtime_final_response": (
                    "[BUDGET] ARIVO 195/55/R16 PREMIO COMFORT 6"
                )
            }
        ],
        tools=SimpleNamespace(store=store),
        product_presentation_history=[],
        latest_product_presentation={},
    )

    _remember_synthetic_product_delivery(harness)

    assert harness.product_presentation_history[-1]["delivery_status"] == "success"
    assert harness.product_presentation_history[-1]["presentation_ref"] == (
        "pres_synthetic_delivery"
    )
    assert [
        card["card_ref"]
        for card in harness.product_presentation_history[-1]["cards"]
    ] == ["card_1"]


