def test_promo_search_hydrates_size_and_zero_eligible_refs_open_semantic_progression():
    signals = [
        {
            "key": "tire_size",
            "value": "195/60R15",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        }
    ]
    hydrated = _hydrate_service_tool_args(
        "search_promo_catalog",
        {"query": "195/60R15", "mode": "general"},
        signals,
    )
    compact = _compact_tool_result(
        "search_promo_catalog",
        {
            "status": "ok",
            "evidence_ref": "promo_search:catalog-v1:scope1",
            "tire_size": "195/60R15",
            "candidate_count": 4,
            "eligible_candidate_count": 0,
            "candidates": [{"promo_ref": "promo:one", "applicability": {"status": "ineligible"}}],
            "allowed_promo_refs": [],
        },
    )

    assert hydrated["tire_size"] == "195/60R15"
    assert compact["eligible_candidate_count"] == 0
    assert compact["evidence_ref"] == "promo_search:catalog-v1:scope1"
    assert "Do not describe candidates as applicable" in compact["composition_guidance"]
    assert "discover_brand_buckets" in compact["composition_guidance"]

def test_brandless_promo_no_match_preserves_product_promo_authority_boundary():
    compact = _compact_tool_result(
        "search_promo_catalog",
        {
            "status": "ok",
            "evidence_ref": "promo_search:catalog-v1:quantity",
            "candidate_count": 0,
            "eligible_candidate_count": 0,
            "candidates": [],
            "allowed_promo_refs": [],
        },
    )

    guidance = compact["composition_guidance"]
    assert "exact catalog search" in guidance
    assert "does not authorize denying product-level" in guidance
    assert "exact-size product_search" in guidance
    assert "Ask for the tire size" in guidance
    assert "do not say that no product-level promo was found" in guidance
    assert "keep availability, applicability, and price pending" in guidance
    assert "In customer-facing wording" in guidance
    assert "never mention catalog, search, provider" in guidance


def test_promo_search_hydration_restores_explicit_brand_omitted_by_model_plan():
    hydrated = _hydrate_service_tool_args(
        "search_promo_catalog",
        {
            "query": "current Buy 3 Get 1 promotions",
            "mode": "targeted",
            "top_k": 1,
        },
        [
            {
                "key": "required_brands",
                "value": ["TOYO"],
                "source": "latest_user_message",
                "status": "mentioned_by_latest_user_message",
            },
            {
                "key": "promo_types",
                "value": ["buy3get1"],
                "source": "latest_user_message",
                "status": "mentioned_by_latest_user_message",
            },
        ],
        current_user_message=(
            "May Buy 3 Get 1 ba ang Toyo? "
            "Kung wala, anong current brands ang meron?"
        ),
    )

    assert hydrated["query"] == (
        "current Buy 3 Get 1 promotions TOYO"
    )
    assert hydrated["_customer_requested_brands"] == ["TOYO"]
    assert hydrated["_customer_query_text"].startswith("May Buy 3 Get 1")
    assert hydrated["top_k"] == 5


def test_product_search_hydration_restores_latest_brand_and_terrain_scope():
    events = []

    hydrated = _hydrate_service_tool_args(
        "product_search",
        {
            "section_width": "265",
            "aspect_ratio": "50",
            "rim_size": "R20",
        },
        [
            {
                "key": "required_brands",
                "value": ["NITTO"],
                "source": "latest_user_message",
            },
            {
                "key": "terrain_types",
                "value": ["all-terrain"],
                "source": "latest_user_message",
            },
        ],
        current_user_message="Looking for Nitto A/T 265/50R20",
        normalization_events=events,
    )

    assert hydrated["required_brands"] == ["NITTO"]
    assert hydrated["brand_match_mode"] == "prefer"
    assert hydrated["terrain_types"] == ["all-terrain"]
    assert {
        event["signal_key"]
        for event in events
        if event.get("type")
        == "tool_arg_restored_from_authoritative_signal"
    } == {"required_brands", "terrain_types"}


