def test_order_faq_uses_active_checkout_metadata_for_payment_facts():
    provider = FakeLiveInstallmentCheckoutMetadataProvider()
    payment = answer_order_faq({"question": "Paano payment, COD or card?"}, canonical_values_provider=provider)
    installation_payment = answer_order_faq(
        {"question": "Paano payment?", "service_type": "installation"},
        canonical_values_provider=provider,
    )
    installment = answer_order_faq({"question": "May 0% installment ba?"}, canonical_values_provider=provider)
    delivery_process = answer_order_faq({"question": "Delivery and payment process?"}, canonical_values_provider=provider)
    courier_question = answer_order_faq(
        {"question": "J&T or LBC pwede for shipping?"},
        canonical_values_provider=provider,
    )
    courier_hints = build_faq_hints("J&T or LBC pwede for shipping?", max_hints=2)

    assert payment["status"] == "ok"
    assert "Current payment options:" in payment["answer"]
    assert "BPI Credit Card Installment 6 months 0%" in payment["answer"]
    assert "Exact availability under Pay Now or Pay Later depends" in payment["answer"]
    assert payment["payment_policy"]["customer_method_categories"] == [
        "GCash",
        "credit/debit cards",
        "installment",
    ]
    compact_payment = _compact_tool_result("answer_policy_faq", payment)
    assert compact_payment["payment_policy"] == {
        "customer_method_categories": [
            "GCash",
            "credit/debit cards",
            "installment",
        ]
    }
    assert "active_methods_by_option" not in compact_payment["payment_policy"]
    assert "not proof that every method applies under both" in payment["composition_hint"]
    assert "Current payment options:" in installation_payment["answer"]
    assert "BPI Credit Card Installment 6 months 0%" in installment["answer"]
    assert "YOKOHAMA" in installment["payment_policy"]["installment_options"][0]["available_brands"]
    assert "Current payment options:" in delivery_process["answer"]
    assert courier_question["faq_id"] == "order_what_is_the_delivery_and_payment_process"
    assert "Current payment options:" in courier_question["answer"]
    assert courier_hints[0]["suggested_tool"] == "answer_order_faq"
    assert courier_hints[0]["faq_id"] == "order_what_is_the_delivery_and_payment_process"
    assert "answer only what applies to the current" in ORDER_POLICY_PROMPT
    assert "ask for tire size as the single next" in ORDER_POLICY_PROMPT
    assert "Do not ask for area/location in the same CTA" in ORDER_POLICY_PROMPT
    assert "do not run installation discovery solely because the location is in\nMetro Manila" in ORDER_POLICY_PROMPT
    assert "delivery remains the active path" in ORDER_POLICY_PROMPT


