def test_model_selected_order_summary_uses_deterministic_presentation_body():
    product_tools = _harness()
    search = product_tools.product_search({"rim_size": "R15", "top_k": 3})
    card = search["product_cards"][0]
    agent = RuntimeV7Harness(
        model_client=OrderSummaryModel(
            presentation_ref=search["presentation_ref"],
            card_ref=card["card_ref"],
            item_ref=card["item_ref"],
        ),
        tools=product_tools,
        default_domains=("product", "order"),
    )
    agent.product_presentation_history = [
        {
            "presentation_ref": search["presentation_ref"],
            "observation_ref": search["observation_ref"],
            "delivery_status": "success",
        }
    ]
    agent.latest_selected_product_context = {
        "product_observation_ref": search["observation_ref"],
        "product_presentation_ref": search["presentation_ref"],
        "product_card_ref": card["card_ref"],
        "product_item_ref": card["item_ref"],
        "product_id": card["product_id"],
        "slug": card["slug"],
    }

    first = agent.run_turn("Sige proceed na sa order yung una")

    assert first["capability_profile"]["selected_domains"] == ["order", "product"]
    assert "build_order_summary" in first["capability_profile"]["exposed_tools"]
    assert first["tool_results"][0]["name"] == "build_order_summary"
