def test_product_faq_tool_uses_query_embedding_vector_search_when_gateway_is_available(monkeypatch):
    class FakeProductFAQEmbeddingGateway:
        def __init__(self):
            self.calls = []

        def embed(self, *, texts, model, metadata=None, dimensions=None):
            self.calls.append(
                {
                    "texts": list(texts),
                    "model": model,
                    "metadata": dict(metadata or {}),
                    "dimensions": dimensions,
                }
            )
            return {
                "vectors": [[1.0, 0.0]],
                "model": model,
                "provider": "fake",
                "latency_ms": 3,
            }

    chunks = [
        {
            "source": "faqs",
            "title": "Are your tires brand new?",
            "text": "Q: Are your tires brand new?\nA: Yes, tires are brand new and distributor-sourced.",
            "doc_id": "faq-brand-new",
            "chunk_id": "faq-brand-new:0",
            "vector": [1.0, 0.0],
        },
        {
            "source": "faqs",
            "title": "Do your tires have a warranty?",
            "text": "Q: Do your tires have a warranty?\nA: Warranty depends on supplier investigation.",
            "doc_id": "faq-warranty",
            "chunk_id": "faq-warranty:0",
            "vector": [0.0, 1.0],
        },
    ]
    monkeypatch.setattr(faq_tools, "_PRODUCT_FAQ_CACHE", None)
    monkeypatch.setattr(faq_tools, "_FAQ_QUERY_EMBEDDING_CACHE", {})
    monkeypatch.setattr(faq_tools, "_FAQ_RETRIEVAL_CACHE", {})
    monkeypatch.setattr(
        faq_tools,
        "_product_rag_chunks",
        lambda: (chunks, {"embedding_model": "fake-embedding-model"}, "test-rag-version"),
    )
    gateway = FakeProductFAQEmbeddingGateway()

    answer = faq_tools.answer_product_faq(
        {"question": "legit bang brand new yung tires?"},
        embedding_gateway=gateway,
    )

    assert answer["status"] == "ok"
    assert answer["title"] == "Are your tires brand new?"
    assert "brand new" in answer["answer"].lower()
    assert answer["retrieval"]["retrieval_method"] == "vector_over_product_classified_rag_subset"
    assert answer["retrieval"]["embedding_status"] == "used"
    assert answer["retrieval"]["query_embedding_model"] == "fake-embedding-model"
    assert answer["retrieval"]["query_vector_dimension"] == 2
    assert gateway.calls[0]["dimensions"] == 2


def test_product_faq_vector_retrieval_cache_avoids_repeat_embedding(monkeypatch):
    class CountingEmbeddingGateway:
        def __init__(self):
            self.calls = 0

        def embed(self, *, texts, model, metadata=None, dimensions=None):
            self.calls += 1
            return {
                "vectors": [[1.0, 0.0]],
                "model": model,
                "provider": "fake",
                "latency_ms": 3,
            }

    chunks = [
        {
            "source": "faqs",
            "title": "Are your tires brand new?",
            "text": "Q: Are your tires brand new?\nA: Yes, tires are brand new.",
            "doc_id": "faq-brand-new",
            "chunk_id": "faq-brand-new:0",
            "vector": [1.0, 0.0],
        },
    ]
    monkeypatch.setattr(faq_tools, "_PRODUCT_FAQ_CACHE", None)
    monkeypatch.setattr(faq_tools, "_FAQ_QUERY_EMBEDDING_CACHE", {})
    monkeypatch.setattr(faq_tools, "_FAQ_RETRIEVAL_CACHE", {})
    monkeypatch.setattr(
        faq_tools,
        "_product_rag_chunks",
        lambda: (chunks, {"embedding_model": "fake-embedding-model"}, "test-rag-version"),
    )
    gateway = CountingEmbeddingGateway()

    first = faq_tools.answer_product_faq({"question": "legit brand new ba tires?"}, embedding_gateway=gateway)
    second = faq_tools.answer_product_faq({"question": "legit brand new ba tires?"}, embedding_gateway=gateway)

    assert gateway.calls == 1
    assert first["retrieval"]["retrieval_method"] == "vector_over_product_classified_rag_subset"
    assert second["retrieval"]["cache_hit"] is True


