def test_unexposed_registered_read_tool_recovers_missing_domain_without_direct_execution():
    record = RuntimeV7Harness(
        model_client=CrossDomainReadRecoveryModel(),
        tools=_harness(),
        service_tools=_service_tools(),
        default_domains=("service",),
    ).run_turn("May tire options at installation ba sa Carmona?")

    initial_tools = {
        schema["function"]["name"]
        for schema in record["llm_calls"][0]["tool_schemas"]
    }
    recovered_tools = {
        schema["function"]["name"]
        for schema in record["llm_calls"][1]["tool_schemas"]
    }
    assert "find_installation_partners" in initial_tools
    assert "product_search" not in initial_tools
    assert {"find_installation_partners", "product_search"}.issubset(
        recovered_tools
    )
    assert [result["name"] for result in record["tool_results"]] == [
        "product_search",
        "find_installation_partners",
    ]
    assert record["tool_retry_events"] == [
        {
            "round": 1,
            "type": "unexposed_read_capability_recovery",
            "domains": ["product"],
            "tool_names_by_domain": {"product": ["product_search"]},
            "policy": "recompile_only_registered_read_tools_without_execution",
        }
    ]
    assert record["capability_profile_history"][1]["stage"] == (
        "unexposed_read_recovery:product"
    )
    assert not any(
        event.get("type") == "tool_not_exposed"
        for event in record.get("tool_guard_events") or []
    )


def test_unexposed_read_recovery_gets_one_bounded_replacement_round_for_product_objective():
    class RecoveryThenPromoThenProductModel:
        def __init__(self):
            self.main_calls = 0

        def complete(self, *, messages, tools, tool_choice="auto"):
            del tools, tool_choice
            self.main_calls += 1
            if self.main_calls == 1:
                return {
                    "content": "",
                    "tool_calls": [
                        {
                            "id": "call_unexposed_service",
                            "name": "find_installation_partners",
                            "args": {
                                "location": "Carmona",
                                "service_type": "installation",
                            },
                        }
                    ],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "tool_calls",
                }
            if self.main_calls == 2:
                return {
                    "content": "",
                    "tool_calls": [
                        {
                            "id": "call_promo_only",
                            "name": "search_promo_catalog",
                            "args": {"query": "promo", "mode": "general"},
                        }
                    ],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "tool_calls",
                }
            if self.main_calls == 3:
                return {
                    "content": "Available promos po.",
                    "tool_calls": [],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "stop",
                }
            assert "Internal runtime tool-use retry" in str(
                messages[-1].get("content") or ""
            )
            return {
                "content": "",
                "tool_calls": [
                    {
                        "id": "call_required_product",
                        "name": "product_search",
                        "args": {
                            "section_width": "185",
                            "aspect_ratio": "60",
                            "rim_size": "R15",
                            "top_k": 2,
                        },
                    }
                ],
                "usage": {},
                "cache_usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }

    signal_client = FakeBackgroundSignalModelClient(
        '{"candidates":[{"key":"tire_size","value":"185/60R15",'
        '"source":"latest_user_message","confidence":"high"}]}'
    )
    model = RecoveryThenPromoThenProductModel()
    record = RuntimeV7Harness(
        model_client=model,
        tools=_harness(),
        service_tools=_service_tools(),
        background_signal_model_client=signal_client,
        max_tool_rounds=3,
    ).run_turn("May promo at installation ba for 185/60R15 sa Carmona?")

    assert model.main_calls == 4
    assert [event["type"] for event in record["tool_retry_events"]] == [
        "unexposed_read_capability_recovery",
        "product_objective_tool_retry",
    ]
    assert [result["name"] for result in record["tool_results"]] == [
        "search_promo_catalog",
        "product_search",
    ]
    assert len(record["llm_calls"]) == 4


