def test_extract_compatible_fitment_uses_canonical_car_make_model_and_preserves_raw_query():
    class CanonicalFitmentHTTPClient(MiniHTTPClient):
        def get_json(self, path, params=None):
            self.get_calls.append({"path": path, "params": dict(params or {})})
            if path == "/car_tire_sizes" and params == {"car_make": "Toyota", "car_model": "Innova"}:
                return [
                    {"section_width": "205", "aspect_ratio": "65", "rim_size": "R15"},
                    {"section_width": "205", "aspect_ratio": "65", "rim_size": "R16"},
                ]
            return []

    runner = ProductSearchRunner(http_client=CanonicalFitmentHTTPClient(), max_api_calls=3)

    result = runner.extract_compatible_fitment(
        {
            "vehicle_query": "innova g 2011",
            "car_make_model": "Toyota Innova",
            "top_k": 3,
        }
    )

    assert result["status"] == "ok"
    assert result["vehicle_query"] == "Toyota Innova"
    assert result["raw_vehicle_query"] == "innova g 2011"
    assert result["query_basis"]["raw_vehicle_query"] == "innova g 2011"
    assert result["attempted_queries"][0]["params"] == {"car_make": "Toyota", "car_model": "Innova"}
    assert [candidate["size"] for candidate in result["candidate_sizes"]] == ["205/65R15", "205/65R16"]
    assert result["presentation_ref"].startswith("pres_fitment_")
    assert result["card_runtime_insert"] is True


def test_extract_compatible_fitment_filters_compatibility_candidates_by_explicit_rim():
    class MixedRimFitmentHTTPClient(MiniHTTPClient):
        def get_json(self, path, params=None):
            self.get_calls.append({"path": path, "params": dict(params or {})})
            if path == "/car_tire_sizes" and params == {"car_make": "Toyota", "car_model": "Innova"}:
                return [
                    {"section_width": "205", "aspect_ratio": "65", "rim_size": "R15"},
                    {"section_width": "225", "aspect_ratio": "50", "rim_size": "R18"},
                    {"section_width": "215", "aspect_ratio": "60", "rim_size": "R17"},
                    {"section_width": "205", "aspect_ratio": "65", "rim_size": "R16"},
                ]
            return []

    runner = ProductSearchRunner(http_client=MixedRimFitmentHTTPClient(), max_api_calls=3)

    result = runner.extract_compatible_fitment(
        {
            "vehicle_query": "Innova rim 15",
            "car_make_model": "Toyota Innova",
            "rim_size": "15",
            "top_k": 6,
        }
    )

    assert result["status"] == "ok"
    assert result["query_basis"]["size_preferences"]["rim_size"] == "R15"
    assert [candidate["size"] for candidate in result["candidate_sizes"]] == ["205/65R15"]
    assert result["size_preference_summary"]["hard_filter_applied"] is True


