def test_runtime_v7_harness_executes_fitment_tool_without_product_cards():
    agent = RuntimeV7Harness(model_client=FitmentCandidateProductModel(), tools=_harness())

    payload = agent.run_conversation(["may pang vios ba kayo?"])
    first = payload["turns"][0]

    assert first["llm_calls"][0]["tool_calls"][0]["name"] == "extract_compatible_fitment"
    assert first["tool_results"][0]["result"]["candidate_sizes"]
    assert first["tool_results"][0]["result"]["presentation_ref"].startswith("pres_fitment_")
    assert first["tool_results"][0]["result"]["card_runtime_insert"] is True
    assert first["first_turn_opening_model_composed"] is True
    assert first["first_turn_intro_mode"] == FIRST_TURN_INTRO_MODE_WELCOME_ONLY
    assert not first["runtime_final_response"].startswith(RUNTIME_V7_WELCOME_SPIEL_TEXT)
    assert not first["runtime_final_response"].startswith(RUNTIME_V7_FIRST_TURN_INTRO_TEXT)
    assert "I found possible tire sizes" in first["runtime_final_response"]
    assert "Possible tire sizes for Toyota Vios" in first["runtime_final_response"]
    assert "- 185/60R15" in first["runtime_final_response"]
    assert "- 175/65R14" in first["runtime_final_response"]
    assert first["observation_headers_after_turn"] == []
    assert agent.latest_fitment_observation["candidate_sizes"]
    assert agent.latest_fitment_observation["requires_customer_confirmation"] is True


def test_runtime_v7_harness_hydrates_fitment_args_from_background_car_make_model():
    class RawInnovaFitmentModel:
        def complete(self, *, messages, tools, tool_choice="auto"):
            if messages[-1].get("role") == "tool":
                return {
                    "content": "Possible sizes po ito. Pa-confirm na lang sa sidewall.",
                    "tool_calls": [],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "stop",
                }
            return {
                "content": "",
                "tool_calls": [
                    {
                        "id": "call_fitment_innova",
                        "name": "extract_compatible_fitment",
                        "args": {"vehicle_query": "innova g 2011", "top_k": 3},
                    }
                ],
                "usage": {},
                "cache_usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }

    signal_client = FakeBackgroundSignalModelClient(
        '{"candidates":[{"key":"car_make_model","value":"Toyota Innova","source":"latest_user_message","confidence":"high"}]}'
    )
    agent = RuntimeV7Harness(
        model_client=RawInnovaFitmentModel(),
        tools=_harness(),
        background_signal_model_client=signal_client,
    )

    payload = agent.run_conversation(["innova g 2011 po hm tires?"])
    first = payload["turns"][0]
    full_result = first["tool_results"][0]["full_result"]

    assert first["tool_results"][0]["args"]["vehicle_query"] == "innova g 2011"
    assert full_result["vehicle_query"] == "Toyota Innova"
    assert full_result["raw_vehicle_query"] == "innova g 2011"
    assert full_result["attempted_queries"][0]["params"] == {"car_make": "Toyota", "car_model": "Innova"}
    assert "Possible tire sizes for Toyota Innova" in first["runtime_final_response"]


