def test_runtime_v7_harness_retries_when_model_skips_needed_product_tool():
    signal_client = FakeBackgroundSignalModelClient(
        '{"candidates":[{"key":"tire_size","value":"185/60R15","source":"latest_user_message","confidence":"high"}]}'
    )
    agent = RuntimeV7Harness(
        model_client=MissingProductToolThenSearchModel(),
        tools=_harness(),
        background_signal_model_client=signal_client,
    )
    agent.memory_updater.seed(
        agent.session_id,
        "Customer is comparing 185/60R15 product options and wants cheaper alternatives.",
        source="test_seed",
    )

    payload = agent.run_conversation(["May mas mura na ibang brand for 185/60R15?"])
    first = payload["turns"][0]

    assert first["tool_retry_events"][0]["type"] == "product_objective_tool_retry"
    assert first["tool_retry_events"][0]["reason"] == "structured_product_objective_unmet"
    assert [result["name"] for result in first["tool_results"]] == ["product_search"]
    assert first["llm_calls"][0]["tool_calls"] == []
    assert first["llm_calls"][1]["tool_calls"][0]["name"] == "product_search"
    assert "hanapan ko" not in first["runtime_final_response"].lower()
    assert "May nakita akong cheaper alternatives" in first["runtime_final_response"]


