def test_compound_order_faq_hydration_preserves_each_customer_backed_call_scope():
    customer_message = (
        "Pwede ba Home Credit? For Yokohama Pay Later, available ba ang "
        "3-month 0% at BPI 6-month 0%?"
    )
    calls = [
        {
            "name": "answer_order_faq",
            "args": {
                "question": "Pwede ba Home Credit?",
                "requested_payment_method": "Home Credit",
                "requested_product_brand": "Yokohama",
            },
        },
        {
            "name": "answer_order_faq",
            "args": {
                "question": "Available ba ang 3-month 0%?",
                "requested_payment_method": "3 months installment 0% interest",
                "requested_product_brand": "Yokohama",
                "payment_option": "Pay Later",
            },
        },
        {
            "name": "answer_order_faq",
            "args": {
                "question": "Available ba ang BPI 6-month 0%?",
                "requested_payment_method": "BPI 6 months installment 0% interest",
                "requested_product_brand": "Yokohama",
                "payment_option": "Pay Later",
            },
        },
    ]
    turn_wide_signals = [
        {
            "key": "payment_method",
            "value": "home credit",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
        {
            "key": "bank",
            "value": "BPI",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
        {
            "key": "installment_months",
            "value": "3",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
        {
            "key": "payment_option",
            "value": "Pay Later",
            "status": "mentioned_unconfirmed",
            "source": "latest_user_message",
        },
    ]

    hydrated = [
        _hydrate_service_tool_args(
            "answer_order_faq",
            call["args"],
            turn_wide_signals,
            current_user_message=customer_message,
            same_turn_tool_calls=calls,
        )
        for call in calls
    ]

    assert [row.get("requested_payment_method") for row in hydrated] == [
        "Home Credit",
        "3 months installment 0% interest",
        "BPI 6 months installment 0% interest",
    ]
    assert hydrated[0].get("requested_product_brand") is None
    assert hydrated[0].get("payment_option") is None
    assert hydrated[1]["requested_product_brand"] == "Yokohama"
    assert hydrated[1]["payment_option"] == "Pay Later"
    assert hydrated[2]["requested_product_brand"] == "Yokohama"
    assert hydrated[2]["payment_option"] == "Pay Later"
    assert len({_tool_execution_cache_key("answer_order_faq", row) for row in hydrated}) == 3


