def test_compound_payment_brand_scope_does_not_cross_two_brand_clauses():
    customer_message = (
        "For Yokohama, available ba ang 3-month 0%, at for Michelin, "
        "available ba ang BPI 6-month 0%?"
    )
    calls = [
        {
            "name": "answer_order_faq",
            "args": {
                "question": "Yokohama 3-month 0%?",
                "requested_payment_method": "3 months installment 0% interest",
                "requested_product_brand": "Yokohama",
            },
        },
        {
            "name": "answer_order_faq",
            "args": {
                "question": "Michelin BPI 6-month 0%?",
                "requested_payment_method": "BPI 6 months installment 0% interest",
                "requested_product_brand": "Michelin",
            },
        },
    ]

    yokohama = _hydrate_service_tool_args(
        "answer_order_faq",
        calls[0]["args"],
        [],
        current_user_message=customer_message,
        same_turn_tool_calls=calls,
    )
    michelin = _hydrate_service_tool_args(
        "answer_order_faq",
        calls[1]["args"],
        [],
        current_user_message=customer_message,
        same_turn_tool_calls=calls,
    )
    wrong_args = {
        **calls[1]["args"],
        "requested_product_brand": "Yokohama",
    }
    wrong = _hydrate_service_tool_args(
        "answer_order_faq",
        wrong_args,
        [],
        current_user_message=customer_message,
        same_turn_tool_calls=[
            {"name": "answer_order_faq", "args": wrong_args}
        ],
    )

    assert yokohama["requested_product_brand"] == "Yokohama"
    assert michelin["requested_product_brand"] == "Michelin"
    assert wrong["requested_product_brand"] == "MICHELIN"


