def test_delivery_question_end_to_end_forces_policy_before_composer():
    model = GroundingContractModel(skip_initial_tool=True)
    signal_model = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "location",
                        "value": "BGC, Taguig, Metro Manila",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                        "evidence": "BGC",
                    },
                    {
                        "key": "service_type",
                        "value": "delivery",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                        "evidence": "Pwede delivery sa BGC?",
                    }
                ]
            }
        )
    )
    harness = RuntimeV7Harness(
        model_client=model,
        tools=_harness(),
        background_signal_model_client=signal_model,
        max_tool_rounds=3,
    )

    turn = harness.run_turn("Pwede delivery sa BGC?")

    assert [item["name"] for item in turn["tool_results"]] == [
        "answer_policy_faq"
    ]
    assert turn["tool_results"][0]["args"]["service_type"] == "delivery"
    assert turn["tool_results"][0]["full_result"]["policy_type"] == (
        "delivery_process"
    )
    assert any(
        event["type"] == "policy_evidence_tool_retry"
        for event in turn["tool_retry_events"]
    )
    assert turn["final_composer"]["status"] == "used", json.dumps(
        turn["response_guard_events"], ensure_ascii=False, indent=2
    )
    scope_obligation = next(
        item
        for item in turn["customer_turn_plan"]["request_obligations"]
        if item["obligation_id"].startswith("scope_boundary:")
    )
    assert scope_obligation["expected_disposition"] == "pending_validation"
    assert "Greater Manila Area" in turn["runtime_final_response"]
    assert "Lalamove" in turn["runtime_final_response"]
    assert "7-10 days" in turn["runtime_final_response"]
    assert "exact-address serviceability" in turn["runtime_final_response"]


