def test_compound_payment_end_to_end_preserves_scopes_through_composer():
    customer_message = (
        "Pwede ba Home Credit? For Yokohama Pay Later, available ba ang "
        "3-month 0% at BPI 6-month 0%?"
    )
    calls = [
        {
            "id": "call_home_credit",
            "name": "answer_order_faq",
            "args": {
                "question": "Pwede ba Home Credit?",
                "requested_payment_method": "Home Credit",
                "requested_product_brand": "Yokohama",
            },
        },
        {
            "id": "call_yokohama_three",
            "name": "answer_order_faq",
            "args": {
                "question": "Yokohama 3-month 0% under Pay Later?",
                "requested_payment_method": "3 months installment 0% interest",
                "requested_product_brand": "Yokohama",
                "payment_option": "Pay Later",
            },
        },
        {
            "id": "call_yokohama_bpi_six",
            "name": "answer_order_faq",
            "args": {
                "question": "BPI 6-month 0%?",
                "requested_payment_method": "BPI 6 months installment 0% interest",
            },
        },
    ]
    model = GroundingContractModel(payment_calls=calls)
    signal_model = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "payment_option",
                        "value": "Pay Later",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                    },
                    {
                        "key": "payment_method",
                        "value": "Home Credit",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                    },
                    {
                        "key": "bank",
                        "value": "BPI",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                    },
                    {
                        "key": "installment_months",
                        "value": "3",
                        "source": "latest_user_message",
                        "confidence": "high",
                        "relation": "question_only",
                    },
                ]
            }
        )
    )
    harness = RuntimeV7Harness(
        model_client=model,
        tools=_harness(),
        background_signal_model_client=signal_model,
        canonical_values_provider=CompoundPaymentCheckoutMetadataProvider(),
        max_tool_rounds=3,
    )

    turn = harness.run_turn(customer_message)

    results = [
        item for item in turn["tool_results"] if item["name"] == "answer_order_faq"
    ]
    assert len(results) == 3
    assert [item["args"]["requested_payment_method"] for item in results] == [
        "Home Credit",
        "3 months installment 0% interest",
        "BPI 6 months installment 0% interest",
    ]
    assert results[0]["args"].get("requested_product_brand") is None
    assert results[0]["args"].get("payment_option") is None
    assert results[1]["args"]["payment_option"] == "Pay Later"
    assert results[2]["args"]["payment_option"] == "Pay Later"
    policies = [item["full_result"]["payment_policy"] for item in results]
    assert policies[0]["requested_payment_status"] == "unsupported"
    assert policies[1]["requested_brand_eligibility"] == "not_brand_restricted"
    assert policies[2]["requested_brand_eligibility"] == "not_eligible"
    assert not any(
        event.get("type") == "duplicate_tool_call_reused"
        for event in turn.get("tool_cache_events") or []
    )
    assert turn["final_composer"]["status"] == (
        "provider_grounded_payment_composition"
    ), json.dumps(
        turn["response_guard_events"], ensure_ascii=False, indent=2
    )
    assert not any(
        event.get("type")
        in {"request_coverage_missing", "unknown_request_coverage_obligation"}
        for event in turn["response_guard_events"]
    )
    assert model.last_composer_payload == {}
    assert any(
        event.get("type") == "provider_grounded_payment_composition_used"
        and event.get("claim_count") == 3
        for event in turn["response_guard_events"]
    )
    assert "Home Credit" in turn["runtime_final_response"]
    assert "3-month 0%" in turn["runtime_final_response"]
    assert "BPI 6-month 0%" in turn["runtime_final_response"]


