def test_multilocation_zero_product_path_repairs_to_scoped_partner_lookup():
    product_tools = _harness()
    product_tools.store.save_search_result(
        {
            "status": "no_match",
            "observation_ref": "obs_nitto_zero_cards",
            "presentation_ref": "pres_nitto_zero_cards",
            "query_basis": {
                "tire_size": "265/50R20",
                "required_brands": ["NITTO"],
            },
            "presentation_strategy": {"card_count": 0},
            "product_cards": [],
            "presented_products": [],
            "best_products": [],
        }
    )
    service_tools = RuntimeV7ServiceTools(
        http_client=RosarioServiceHTTPClient(),
        geocode_api_key="",
    )
    signal_client = FakeBackgroundSignalModelClient(
        json.dumps(
            {
                "candidates": [
                    {
                        "key": "location",
                        "value": "Rosario Cavite",
                        "source": "latest_user_message",
                        "confidence": "high",
                    },
                    {
                        "key": "acceptable_service_locations",
                        "value": ["Dasmarinas", "Imus", "Bacoor"],
                        "source": "latest_user_message",
                        "confidence": "high",
                    },
                    {
                        "key": "service_type",
                        "value": "installation",
                        "source": "latest_user_message",
                        "confidence": "high",
                    },
                ]
            }
        )
    )
    agent = RuntimeV7Harness(
        model_client=MultiLocationIntegratedContractModel(),
        tools=product_tools,
        service_tools=service_tools,
        background_signal_model_client=signal_client,
        max_tool_rounds=4,
    )

    turn = agent.run_turn(
        "I'm from Rosario, Cavite. Okay din sa Dasmarinas, Imus, o Bacoor "
        "kung may installation partner."
    )

    assert [row["name"] for row in turn["tool_results"]] == [
        "find_installation_slots",
        "find_installation_partners",
    ]
    rejected, grounded = turn["tool_results"]
    assert rejected["full_result"]["status"] == "not_applicable"
    assert rejected["full_result"]["outcome_type"] == (
        "deterministic_progression_redirect"
    )
    assert rejected["args"]["location"] == "Rosario, Cavite"
    assert grounded["model_args"]["location"] == "Bacoor City, Cavite"
    assert grounded["args"]["location"] == "Rosario, Cavite"
    assert grounded["full_result"]["status"] == "ok"
    assert grounded["result"]["service_claim_scope"]["queried_location"] == (
        "Rosario, Cavite"
    )
    assert turn["customer_turn_plan"]["progression_context"][
        "current_service_answer_scope"
    ]["repeat_prior_product_result"] is False
    assert turn["final_composer"]["status"] == (
        "service_claim_surface_sanitized"
    )
    assert agent.model_client.composer_calls == 1
    assert any(
        event.get("type")
        == "provider_owned_service_claim_prose_sanitized"
        and event.get("removed_response_unit_count") == 1
        for event in turn["response_guard_events"]
    )
    assert "Rosario, Cavite" in turn["runtime_final_response"]
    assert "1 current installation partner option" in turn[
        "runtime_final_response"
    ]
    assert "Nitto" not in turn["runtime_final_response"]
    assert "Dasmarinas" not in turn["runtime_final_response"]
    assert "Imus" not in turn["runtime_final_response"]
    assert "Bacoor" not in turn["runtime_final_response"]


