def test_runtime_v7_harness_reuses_semantically_duplicate_product_search():
    class CountingHarness(RuntimeV7Harness):
        def __init__(self, **kwargs):
            super().__init__(**kwargs)
            self.executed_tool_names = []

        def _execute_tool(self, name, args, **kwargs):
            self.executed_tool_names.append(name)
            return super()._execute_tool(name, args, **kwargs)

    model = DuplicateEquivalentProductSearchModel()
    agent = CountingHarness(
        model_client=model,
        tools=_harness(),
        max_tool_rounds=4,
    )

    payload = agent.run_conversation(["185/60R15 budget options for 4 pcs"])
    first = payload["turns"][0]

    assert agent.executed_tool_names.count("product_search") == 1
    assert [result["name"] for result in first["tool_results"]] == ["product_search"]
    assert first["tool_dedupe_events"][0]["type"] == "duplicate_tool_call_reused"
    assert first["tool_dedupe_events"][0]["name"] == "product_search"
    assert first["tool_dedupe_events"][0]["presentation_ref"].startswith("pres_product_search_")
    assert model.tool_messages[-1]["reused_tool_result"] is True
    assert model.tool_messages[-1]["presentation_ref"] == first["tool_results"][0]["result"]["presentation_ref"]




