def test_find_installation_partners_uses_size_only_filters_and_keeps_brand_model_advisory():
    class BrandPatternServiceHTTPClient(MiniServiceHTTPClient):
        def get_json(self, path, *, params=None):
            if path == "/branch_list_loc":
                self.get_calls.append({"path": path, "params": dict(params or {})})
                return []
            if path in {"/all_branch", "/branch_list"}:
                self.get_calls.append({"path": path, "params": dict(params or {})})
                return [
                    {
                        "id": 501,
                        "name": "APOLLO COMPATIBLE PARTNER",
                        "area": "General Trias",
                        "city": "General Trias",
                        "province": "Cavite",
                        "address": "General Trias, Cavite",
                        "lat": "14.3215",
                        "lng": "120.9073",
                        "active": True,
                        "brand": "APOLLO",
                        "pattern": "AMAZER",
                        "section_width": "175",
                        "aspect_ratio": "65",
                        "rim_size": "R14",
                    },
                    {
                        "id": 502,
                        "name": "MICHELIN ONLY PARTNER",
                        "area": "General Trias",
                        "city": "General Trias",
                        "province": "Cavite",
                        "address": "General Trias, Cavite",
                        "lat": "14.3220",
                        "lng": "120.9078",
                        "active": True,
                        "brand": "MICHELIN",
                        "pattern": "PRIMACY",
                        "section_width": "175",
                        "aspect_ratio": "65",
                        "rim_size": "R14",
                    },
                ]
            return super().get_json(path, params=params)

    service_tools = RuntimeV7ServiceTools(http_client=BrandPatternServiceHTTPClient(), geocoder=FakeGeocoder())

