def test_turn_plan_carries_selected_product_evidence_into_service_transition():
    from runtime_v7.runtime_harness import _build_customer_turn_plan

    plan = _build_customer_turn_plan(
        record={"tool_results": []},
        order_readiness={"collected": {"Product": "Continental UltraContact"}},
        draft_assistant_text="May schedules po near Alabang.",
        selected_product_context={
            "product_observation_ref": "obs_product_varied_transition",
            "product_presentation_ref": "pres_product_varied_transition",
            "product_summary": {
                "brand": "CONTINENTAL",
                "sku_model": "CONTINENTAL 225/45/R18 ULTRACONTACT UC7",
                "tire_size": "225/45R18",
            },
        },
    )

    for category in ("product_facts", "validated_state"):
        assert category in plan["authorized_claim_categories"]
        assert plan["progression_context"][
            "authorized_evidence_refs_by_claim_category"
        ][category] == [
            "obs_product_varied_transition",
            "pres_product_varied_transition",
        ]
    assert plan["progression_context"]["selected_product_transition"][
        "sku_model"
    ] == "CONTINENTAL 225/45/R18 ULTRACONTACT UC7"


def test_find_installation_slots_rejects_delivery_without_partner_no_match():
    service_tools = RuntimeV7ServiceTools(http_client=MiniServiceHTTPClient(), geocoder=FakeGeocoder())

    result = service_tools.find_installation_slots(
        {
            "location": "Quezon City",
            "service_type": "delivery",
            "preferred_schedule_candidates": [
                {
                    "date_start": "2026-06-15",
                    "date_end": "2026-06-21",
                    "label": "next week",
                    "source_phrase": "nxtweek cguro",
                }
            ],
            "source_schedule_phrase": "nxtweek cguro",
            "request_time": "2026-06-08 14:48:39",
        }
    )
    compact = _compact_tool_result("find_installation_slots", result)
    compact_text = json.dumps(compact, ensure_ascii=False).lower()

    assert result["status"] == "not_applicable_for_delivery"
    assert result["installation_partners"] == []
    assert result["installation_partner_cards"] == []
    assert result["lookup_observation_ref"] is None
    assert result["availability"]["availability_status"] == "not_applicable_for_delivery"
    assert compact["schedule_semantics"]["availability_status"] == "not_applicable_for_delivery"
    assert "recommended_next_step" not in compact_text
    assert "recommended next step" not in compact_text
    assert "installation slots require a separate lookup" in compact["note"].lower()
    assert "no_installation_partner_match" not in compact_text
    assert "do not say no installation partner matched" in compact["note"].lower()


