def test_product_search_quantity_does_not_treat_visible_slot_day_as_tire_count():
    store = ProductObservationStore()
    store.save_search_result(
        {
            "observation_ref": "obs_product_qty",
            "presentation_ref": "pres_product_qty",
            "product_cards": [
                {
                    "card_ref": "card_1",
                    "item_ref": "prod_1",
                    "brand": "APOLLO",
                    "quantity": 4,
                }
            ],
        }
    )
    product_tools = ProductToolHarness(store=store)
    service_tools = RuntimeV7ServiceTools(http_client=MiniServiceHTTPClient(), geocoder=FakeGeocoder())
    service_tools.store.save_installation_slots_result(
        {
            "observation_ref": "svc_slots_qty",
            "presentation_ref": "pres_slots_qty",
            "slot_groups": [
                {
                    "slots": [
                        {"slot_ref": "slot_1", "date": "2026-06-05", "time": "16:30"},
                    ]
                }
            ],
        }
    )
    events = []

    hydrated = _hydrate_service_tool_args(
        "product_search",
        {"section_width": "185", "aspect_ratio": "65", "rim_size": "R15", "quantity": 5},
        [{"key": "latest_service_presentation", "value": "svc_slots_qty / pres_slots_qty"}],
        product_tools=product_tools,
        service_tools=service_tools,
        normalization_events=events,
    )

    assert hydrated["quantity"] == 4
    assert events == [
        {
            "type": "product_quantity_restored_from_visible_product_context",
            "model_quantity": 5,
            "restored_quantity": 4,
            "reason": "model_quantity_matched_visible_service_slot_day_number",
            "slot_day_numbers": [5],
        }
    ]

    explicit_quantity = _hydrate_service_tool_args(
        "product_search",
        {"section_width": "185", "aspect_ratio": "65", "rim_size": "R15", "quantity": 5},
        [{"key": "quantity", "value": "5", "source": "latest_user_message"}],
        product_tools=product_tools,
        service_tools=service_tools,
        normalization_events=[],
    )

    assert explicit_quantity["quantity"] == 5


