def test_find_installation_partners_falls_back_to_city_text_match_when_geocoded_rows_lack_coordinates():
    class ImusGeocoder:
        def geocode(self, address):
            if "imus" in str(address or "").lower():
                return {"lat": 14.4297, "lng": 120.9367}
            return {}

    class NoCoordinateImusHTTPClient(MiniServiceHTTPClient):
        def get_json(self, path, *, params=None):
            if path == "/get_city":
                return [
                    *super().get_json(path, params=params),
                    {"CITY_CODE": "PH-CAV-IMS", "CITY_NAME": "IMUS", "PROV_CODE": "PH-CAV"},
                ]
            if path in {"/branch_list_loc", "/branch_list", "/all_branch"}:
                self.get_calls.append({"path": path, "params": dict(params or {})})
                return [
                    {
                        "id": 401,
                        "name": "BAE AUTO SERVICE",
                        "area": "Imus",
                        "city": "Imus",
                        "province": "Cavite",
                        "address": "Imus, Cavite",
                        "active": True,
                    },
                    {
                        "id": 402,
                        "name": "TRESH TIRE TRADING",
                        "area": "General Trias",
                        "city": "General Trias",
                        "province": "Cavite",
                        "address": "General Trias, Cavite",
                        "active": True,
                    },
                ]
            return super().get_json(path, params=params)

    service_tools = RuntimeV7ServiceTools(http_client=NoCoordinateImusHTTPClient(), geocoder=ImusGeocoder())

    result = service_tools.find_installation_partners({"location": "Imus Cavite", "service_type": "installation"})

