def test_location_resolver_retries_google_geocode_failures(monkeypatch):
    responses = [
        {"status": "REQUEST_DENIED", "error_message": "The provided API key is expired."},
        {"status": "UNKNOWN_ERROR", "error_message": "temporary geocoder issue"},
        {"status": "OK", "results": [{"geometry": {"location": {"lat": 9.5694, "lng": 123.7872}}}]},
    ]
    calls = []

    class FakeResponse:
        status_code = 200
        text = ""

        def __init__(self, payload):
            self._payload = payload

        def json(self):
            return self._payload

    def fake_get(url, *, params=None, timeout=None):
        calls.append({"url": url, "params": dict(params or {}), "timeout": timeout})
        payload = responses[min(len(calls) - 1, len(responses) - 1)]
        return FakeResponse(payload)

    monkeypatch.setattr("runtime_v7.location_resolution.requests.get", fake_get)
    resolver = RuntimeV7LocationResolver(
        http_client=MiniServiceHTTPClient(),
        api_key="fake-key",
        geocode_retry_attempts=2,
        geocode_retry_backoff_s=0,
    )

    result = resolver.resolve("panglao")

    assert result["status"] == "geocoded"
    assert result["coordinates"] == {"lat": 9.5694, "lng": 123.7872}
    assert result["geocode_attempts"] == 3
    assert result["geocode_last_status"] == "OK"
    assert len(calls) == 3


