def test_runtime_v7_business_location_boundary_repairs_complementary_failures():
    ambiguous_model = StaticPlainTextModel(
        "Ang head office namin ay nasa 1166 Chino Roces Avenue, Makati City."
    )
    ambiguous_agent = RuntimeV7Harness(
        model_client=ambiguous_model,
        tools=_harness(),
    )
    ambiguous_turn = ambiguous_agent.run_conversation(
        ["location ng store?"]
    )["turns"][0]

    assert ambiguous_turn["runtime_final_response"] == (
        "Saang city o area po kayo naghahanap?"
    )
    assert ambiguous_turn["assistant_text"] == ambiguous_turn[
        "runtime_final_response"
    ]
    assert ambiguous_turn["capability_profile"]["exposed_tools"] == []
    ambiguous_render = render_turn_for_channel(ambiguous_turn)
    assert "1166 Chino Roces" not in ambiguous_render.text
    assert "Saang city o area" in ambiguous_render.text
    assert ambiguous_turn["response_guard_events"][-1]["type"] == (
        "business_location_response_boundary"
    )

    explicit_model = StaticPlainTextModel("Pasensya po, paki-send ulit.")
