def test_runtime_v7_harness_captures_context_tool_calls_and_cross_turn_observations():
    seed_memory = "Customer mentioned current tire is 195/55R15 but is not sure if it is the original size."
    agent = RuntimeV7Harness(model_client=ScriptedRuntimeV7Model(), tools=_harness())
    agent.memory_updater.seed(agent.session_id, seed_memory, source="test_seed")

    first_turn = agent.run_turn(
        "May Yokohama 185/60 R15? Budget around 5000 each."
    )
    first_observation = agent.tools.store.latest()
    assert first_observation is not None
    agent.product_presentation_history = [
        {
            "presentation_ref": first_observation.presentation_ref,
            "observation_ref": first_observation.observation_ref,
            "delivery_status": "success",
        }
    ]
    second_turn = agent.run_turn("Yun una may installment?")
    third_turn = agent.run_turn("May mas mura na ibang brand?")
    payload = {
        "turn_count": 3,
        "turns": [first_turn, second_turn, third_turn],
        "final_observation_headers": agent.tools.store.headers(limit=3),
    }

    assert payload["turn_count"] == 3
    first = payload["turns"][0]
    assert "## Current Customer Message" in first["context_input"]
    assert "## Capability Surface" not in first["context_input"]
    assert first["capability_profile"]["exposed_tools"]
    assert "## Active Working Memory" in first["context_input"]
    if first["background_signals_before_turn"]:
        assert "## Background Signals" in first["context_input"]
    else:
        assert "## Background Signals" not in first["context_input"]
    assert "## Missing Information / Readiness" in first["context_input"]
    assert "195/55R15" in first["context_input"]
    assert first["capability_profile"]["selected_domains"] == [
        "order",
        "product",
        "service",
    ]
    first_schema_names = {schema["function"]["name"] for schema in first["llm_calls"][0]["tool_schemas"]}
    assert {"product_search", "discover_brand_buckets", "extract_compatible_fitment", "request_capability"}.issubset(first_schema_names)
    assert "get_product_details" not in first_schema_names
    assert first["missing_info_before_turn"]["order_readiness"]["status"] == "not_ready"
    assert first["llm_calls"][0]["tool_calls"][0]["name"] == "product_search"
    assert first["llm_calls"][0]["tool_schemas"]
    assert first["tool_results"][0]["result"]["product_card_headers"]
    assert first["tool_results"][0]["result"]["cards_will_be_inserted_by_runtime"] is True
    assert first["tool_results"][0]["full_result"]["product_cards"]
    assert first["assistant_text"]
    assert "YOKOHAMA" in first["runtime_final_response"]
    assert {
        card["brand"]
        for card in first["tool_results"][0]["full_result"]["product_cards"]
    } == {"YOKOHAMA"}
    assert first["observation_headers_after_turn"]
    assert first["active_working_memory_before_turn"]["text"] == seed_memory
    assert "product search presented" in first["active_working_memory_after_turn"]["text"]

    second = payload["turns"][1]
    assert "Last Product Presentation" in second["context_input"]
    assert "card_1" in second["context_input"]
    second_schema_names = {schema["function"]["name"] for schema in second["llm_calls"][0]["tool_schemas"]}
    assert "resolve_product_reference" in second_schema_names
    assert "get_product_details" in second_schema_names
    detail_call = second["llm_calls"][0]["tool_calls"][0]
    assert detail_call["name"] == "get_product_details"
    assert detail_call["args"]["ordinal"] == 1
    assert second["tool_results"][0]["result"]["status"] == "ok"

    third = payload["turns"][2]
    assert "Yun una may installment?" in third["context_input"]
    assert third["llm_calls"][0]["tool_calls"][0]["name"] == "product_search"
    assert payload["final_observation_headers"]
    assert third["active_working_memory_after_turn"]["text"]


