def test_runtime_final_response_uses_model_repair_for_unsupported_visible_card_pricing_arithmetic():
    store = ProductObservationStore()
    store.save_search_result(
        {
            "observation_ref": "obs_yoko_pricing",
            "presentation_ref": "pres_yoko_pricing",
            "product_cards": [
                {
                    "card_ref": "card_1",
                    "item_ref": "prod_yoko_15565r14",
                    "brand": "YOKOHAMA",
                    "sku_model": "YOKOHAMA 155/65/R14 BLUEARTH ES32 75T",
                    "deal_price_line": "PHP 5,420.00/tire | PHP 17,029.60 if for 4 tires",
                    "promo_savings_line": "YOKOHAMA Promo: PHP 1,000.00 off/tire | Bundle: Save PHP 650.40\nSave PHP 4,650.40!",
                    "pricing_facts": {
                        "quantity": 4,
                        "unit_price": 5420.0,
                        "payable_total": 17029.6,
                        "payable_total_text": "PHP 17,029.60 if for 4 tires",
                        "total_savings": 4650.4,
                        "total_savings_text": "PHP 4,650.40",
                        "payable_total_already_includes_savings": True,
                    },
                }
            ],
        }
    )
    guard_events = []
    repair_calls = []

    response = _compose_runtime_final_response(
        "Yes po, tama po ang calculation niyo. Total for 4 tires ay PHP 17,029.60, at may savings PHP 4,650.40. So ang babayaran niyo po ay PHP 12,379.20.",
        [],
        product_observation_store=store,
        pricing_repair_callback=lambda draft, card, unsupported: repair_calls.append(
            {"draft": draft, "card": card, "unsupported": list(unsupported)}
        )
        or (
            "PHP 17,029.60 na po ang discounted total for 4 tires. "
            "Hindi na po ibabawas ulit yung PHP 4,650.40; included na po iyon sa price."
        ),
        guard_events=guard_events,
    )

    assert "PHP 17,029.60" in response
    assert "PHP 4,650.40" in response
    assert "PHP 12,379.20" not in response
    assert "discounted total" in response
    assert repair_calls and repair_calls[0]["unsupported"] == [12379.2]
    assert [event["type"] for event in guard_events] == [
        "unsupported_product_pricing_repair_requested",
        "unsupported_product_pricing_model_repaired",
        "response_unit_recovery",
    ]


