def test_runtime_harness_pricing_repair_uses_structured_low_token_model_call():
    class PricingRepairModel:
        def __init__(self):
            self.calls = []

        def complete(self, *, messages, tools, tool_choice="auto", response_format=None, max_tokens=None):
            self.calls.append(
                {
                    "messages": messages,
                    "tools": tools,
                    "tool_choice": tool_choice,
                    "response_format": response_format,
                    "max_tokens": max_tokens,
                }
            )
            return {
                "content": json.dumps(
                    {
                        "response_text": (
                            "PHP 17,029.60 na po ang discounted total for 4 tires. "
                            "Hindi na po ibabawas ulit yung PHP 4,650.40."
                        ),
                        "used_amounts": ["PHP 17,029.60", "PHP 4,650.40"],
                        "reason": "corrected double-subtracted savings",
                    }
                ),
                "usage": {"input_tokens": 50, "output_tokens": 24},
                "latency_ms": 11,
            }

    model = PricingRepairModel()
    agent = RuntimeV7Harness(model_client=model, tools=_harness())
    record = {"llm_calls": [], "response_guard_events": []}
    card = {
        "card_ref": "card_1",
        "brand": "YOKOHAMA",
        "sku_model": "YOKOHAMA 155/65/R14 BLUEARTH ES32 75T",
        "pricing_facts": {
            "quantity": 4,
            "payable_total": 17029.6,
            "payable_total_text": "PHP 17,029.60 if for 4 tires",
            "total_savings": 4650.4,
            "total_savings_text": "PHP 4,650.40",
            "payable_total_already_includes_savings": True,
        },
    }

    repaired = agent._repair_unsupported_visible_product_pricing(
        current_user_message="17029 less pa ng 4650?",
        draft_response="So ang babayaran niyo po ay PHP 12,379.20.",
        card=card,
        unsupported_amounts=[12379.2],
        record=record,
    )

    assert "PHP 17,029.60" in repaired
    assert model.calls[0]["tool_choice"] == "none"
    assert model.calls[0]["tools"] == []
    assert model.calls[0]["response_format"].__name__ == "RuntimeV7PricingRepairResponseModel"
    assert model.calls[0]["max_tokens"] == PRICING_REPAIR_MAX_TOKENS
    assert record["llm_calls"][0]["component"] == "pricing_repair"
    assert record["llm_calls"][0]["response_format"] == "RuntimeV7PricingRepairResponseModel"


