def test_clarification_only_interaction_rejects_mutating_tool_when_schema_is_empty():
    packet = {
        "schema_version": 1,
        "batch_ref": "interaction:evt-premium:evt-budget",
        "runtime_relation": "same_layer_distinct",
        "allowed_model_interpretations": ["clarify"],
        "state_commit_deferred": True,
        "events": [
            {
                "event_id": "evt-premium",
                "choice_ref": "price_category:premium",
                "choice_type": "price_category",
                "decision_layer": "price_category",
                "label": "Premium",
            },
            {
                "event_id": "evt-budget",
                "choice_ref": "price_category:budget",
                "choice_type": "price_category",
                "decision_layer": "price_category",
                "label": "Budget",
            },
        ],
    }

    class AdversarialClarificationModel:
        def __init__(self):
            self.main_calls = 0

        def complete(
            self,
            *,
            messages,
            tools,
            tool_choice="auto",
            response_format=None,
            max_tokens=None,
        ):
            del tool_choice, max_tokens
            if response_format is not None:
                return {
                    "content": json.dumps(
                        {
                            "interaction_decision": {
                                "interpretation": "clarify",
                                "effective_event_ids": [],
                                "reason_code": "same_layer_without_context",
                                "needs_clarification": True,
                            },
                            "response_units": [
                                {
                                    "type": "text",
                                    "content": {
                                        "text": "Premium po ba o Budget?"
                                    },
                                }
                            ],
                        }
                    ),
                    "tool_calls": [],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "stop",
                }
            self.main_calls += 1
            assert tools == []
            if messages[-1].get("role") == "tool":
                return {
                    "content": "Premium po ba o Budget?",
                    "tool_calls": [],
                    "usage": {},
                    "cache_usage": {},
                    "latency_ms": 1,
                    "finish_reason": "stop",
                }
            return {
                "content": "",
                "tool_calls": [
                    {
                        "id": "call_forbidden_submit",
                        "name": "submit_order",
                        "args": {"order_payload_ref": "order_payload_fake"},
                    }
                ],
                "usage": {},
                "cache_usage": {},
                "latency_ms": 1,
                "finish_reason": "tool_calls",
            }

    class CountingHarness(RuntimeV7Harness):
        def __init__(self, **kwargs):
            super().__init__(**kwargs)
            self.executed_tool_names = []

        def _execute_tool(self, name, args, **kwargs):
            self.executed_tool_names.append(name)
            return super()._execute_tool(name, args, **kwargs)

    agent = CountingHarness(
        model_client=AdversarialClarificationModel(),
        tools=_harness(),
    )
    turn = agent.run_turn(
        "I selected Budget after Premium.",
        interaction_packet=packet,
    )

    assert agent.executed_tool_names == []
    assert turn["tool_results"][0]["name"] == "submit_order"
    assert turn["tool_results"][0]["result"]["error_type"] == (
        "tool_not_exposed"
    )
    assert turn["tool_guard_events"][0]["allowed_tools"] == []
    assert turn["latest_order_payload_ref_after_turn"] == ""


