    assert {"ATLAS", "YOKOHAMA", "MICHELIN"}.issubset(brands)
    assert "composition_requirements" not in payload
    requirements = " ".join(FINAL_COMPOSER_SYSTEM_PROMPT.lower().split())
    assert "card number" in requirements
    assert "no deterministic stage" in requirements
    assert "visible_product_context" in requirements


