def test_service_no_match_unit_contract_defers_other_surfaces_structurally():
    service_tools = RuntimeV7ServiceTools(
        http_client=MiniServiceHTTPClient(),
        geocode_api_key="",
    )
    service_result = service_tools.find_installation_partners(
        {"location": "Panglao", "top_k": 3}
    )
    product_ref = "product_surface_unrelated"
    tool_results = [
        {
            "name": "find_installation_partners",
            "full_result": service_result,
        },
        {
            "name": "product_search",
            "full_result": {
                "status": "ok",
                "presentation_ref": product_ref,
                "product_cards": [
                    {"card_ref": "product_1", "sku_model": "APOLLO TEST"}
                ],
            },
        },
    ]
    surfaces = _final_composer_presentation_surfaces(tool_results)
    service_ref = next(
        str(surface["surface_ref"])
        for surface in surfaces
        if surface.get("type") == "service_no_match_context"
    )
    units = [
        {"type": "text", "content": {"text": "Noted po."}},
        {"type": "render_surface", "content": {"surface_ref": service_ref}},
        {"type": "text", "content": {"text": "Another question?"}},
        {"type": "render_surface", "content": {"surface_ref": product_ref}},
    ]

    violations = _final_composer_renderer_contract_violations(
        units,
        tool_results,
    )
    fallback = _enforce_renderer_owned_unit_contract(units, tool_results)

    assert not {
        "unit_after_renderer_owned_next_input",
        "deferred_surface_rendered",
    } & {item["type"] for item in violations}
    assert fallback == units


def test_runtime_final_response_allows_no_walkin_policy_but_blocks_walkin_claims():
    service_tools = RuntimeV7ServiceTools(http_client=MiniServiceHTTPClient(), geocoder=FakeGeocoder())
    result = service_tools.find_installation_partners({"location": "SM Fairview", "top_k": 1})

    no_walkin_response = _compose_runtime_final_response(
        "No walk-in setup po tayo; kailangan muna ng reservation bago pumunta sa installation site.\n\n"
        "Okay po ba sa inyo itong option?",
        [{"name": "find_installation_partners", "full_result": result}],
    )
    unsafe_walkin_response = _compose_runtime_final_response(
        "Pwede po kayo mag walk-in directly sa branch.\n\nOkay po ba ito?",
        [{"name": "find_installation_partners", "full_result": result}],
    )

    assert "No walk-in setup po tayo" in no_walkin_response
    assert "reservation bago pumunta" in no_walkin_response
    assert "Pwede po kayo mag walk-in" not in unsafe_walkin_response
    assert "current installation partner option" in unsafe_walkin_response
    assert "Pwede po kayo mag walk-in" not in unsafe_walkin_response
    policy_notes = {note["id"]: note["text"] for note in result["service_policy_notes"]}
    assert policy_notes["no_walkin_setup"].startswith("🚫 Paalala po:")


