def test_failed_payment_composer_keeps_grounded_product_card(monkeypatch):
    monkeypatch.setenv(
        "PRICE_CATEGORY_STAGING_ROUTER_FLOW_NAMESPACE",
        "staging_router",
    )
    signal_client = SequencedBackgroundSignalModelClient(
        [
            '{"candidates":['
            '{"key":"tire_size","value":"185/60R15",'
            '"source":"latest_user_message","confidence":"high"}'
            "]}"
        ]
    )
    agent = RuntimeV7Harness(
        model_client=FailingPaymentComposerProductModel(),
        tools=_image_backed_harness(),
        background_signal_model_client=signal_client,
    )

    turn = agent.run_turn("Show me 185/60R15 products first.")
    rendered = render_turn_for_channel(
        turn,
        service_environment="staging",
    )

    assert turn["final_composer"]["status"] == (
        "payment_claim_safe_surface_fallback"
    )
    assert any(
        event.get("type")
        == "payment_claim_safe_surface_fallback_used"
        and event.get("preserved_surface_count") == 1
        for event in turn["response_guard_events"]
    )
    assert "GCash" not in rendered.text
    assert "card installment" not in rendered.text
    assert "We have options for the requested tire size" in rendered.text
    cards = [
        message
        for message in rendered.content_messages
        if message.get("type") == "cards"
    ]
    assert cards
    assert cards[0]["elements"][0]["buttons"][0]["actions"][0][
        "value"
    ].startswith("ps1|")


