def test_final_composer_payload_exposes_runtime_first_turn_intro_guidance():
    messages = _build_final_composer_messages(
        current_user_message="hm 185 60 r15",
        request_time="2026-06-04 17:00:00",
        active_working_memory="",
        recent_turns=[],
        background_signals=[],
        lead_qualification={},
        order_readiness={},
        capability_profile={"selected_domains": ["product"]},
        tool_results=[],
        draft_assistant_text="May available options po tayo for that size.",
        first_turn_intro_context=_first_turn_intro_context_for_model(FIRST_TURN_INTRO_MODE_WELCOME_ONLY),
    )
    payload = json.loads(messages[-1]["content"])

    assert payload["first_turn_intro_context"]["runtime_will_prepend"] is False
    assert payload["first_turn_intro_context"]["model_will_compose"] is True
    assert payload["first_turn_intro_context"]["opening_required"] is True
    assert payload["first_turn_intro_context"]["mode"] == FIRST_TURN_INTRO_MODE_WELCOME_ONLY
    assert payload["first_turn_intro_context"]["composition"] == (
        "model_composes_complete_first_text_before_surfaces"
    )
    assert "Compose the complete first customer-facing text bubble" in (
        payload["first_turn_intro_context"]["model_instruction"]
    )
    assert "Vary the greeting and phrasing" in (
        payload["first_turn_intro_context"]["model_instruction"]
    )
    assert "Use first_turn_intro_context when present" in FINAL_COMPOSER_SYSTEM_PROMPT
    assert "mode=full_intake remains a runtime-" in FINAL_COMPOSER_SYSTEM_PROMPT
    assert "customer-visible response as one coherent turn" in (
        FINAL_COMPOSER_SYSTEM_PROMPT
    )
    assert "fixed welcome copy only if" in FINAL_COMPOSER_SYSTEM_PROMPT


