class FakeMemoryModelClient:
    def __init__(self, content):
        self.content = content
        self.system_prompt = ""
        self.user_prompt = ""

    def generate_memory(self, *, system_prompt, user_prompt, metadata=None):
        self.system_prompt = system_prompt
        self.user_prompt = user_prompt
        return {
            "content": self.content,
            "usage": {"prompt_tokens": 10, "completion_tokens": 5, "total_tokens": 15},
            "cache_usage": {},
            "latency_ms": 12,
            "finish_reason": "stop",
            "model": "gemini/gemini-2.5-flash-lite",
        }


class SequencedMemoryModelClient:
    def __init__(self, sequence):
        self.sequence = list(sequence)
        self.calls = []
        self.system_prompt = ""
        self.user_prompt = ""

    def generate_memory(self, *, system_prompt, user_prompt, metadata=None):
        self.system_prompt = system_prompt
        self.user_prompt = user_prompt
        self.calls.append(dict(metadata or {}))
        if not self.sequence:
            raise RuntimeError("no memory response")
        item = self.sequence.pop(0)
        if isinstance(item, BaseException):
            raise item
        return {
            "content": item,
            "usage": {"prompt_tokens": 20, "completion_tokens": 7, "total_tokens": 27},
            "cache_usage": {},
            "latency_ms": 14,
            "finish_reason": "stop",
            "model": "gemini/gemini-2.5-flash-lite",
        }


def test_turn_usage_includes_background_extraction_and_memory_compaction():
    class MeteredPlainModel:
        def complete(
            self,
            *,
            messages,
            tools,
            tool_choice="auto",
            response_format=None,
            max_tokens=None,
        ):
            content = "Salamat din po!"
            if response_format is not None:
                content = (
                    '{"response_units":[{"type":"text","content":'
                    '{"text":"Salamat din po!"}}]}'
                )
            return {
                "content": content,
                "tool_calls": [],
                "usage": {
                    "prompt_tokens": 100,
                    "completion_tokens": 20,
                    "total_tokens": 120,
                },
                "cache_usage": {},
                "latency_ms": 7,
                "finish_reason": "stop",
                "model": "main-model",
            }

    memory_client = FakeMemoryModelClient(
        '{"active_working_memory":"The customer closed the exchange politely."}'
    )
    harness = RuntimeV7Harness(
        model_client=MeteredPlainModel(),
        tools=_harness(),
        service_tools=_service_tools(),
        background_signal_model_client=FakeBackgroundSignalModelClient(
            '{"candidates":[]}'
        ),
        memory_generator=HybridActiveWorkingMemoryGenerator(
            model_client=memory_client
        ),
    )

    turn = harness.run_turn("Salamat po.")

    supplemental = turn["supplemental_llm_calls"]
    components = {call["component"] for call in supplemental}
    base_tokens = sum(
        call["usage_summary"]["total_tokens"] for call in turn["llm_calls"]
    )
    assert components == {
        "background_signal_extraction",
        "active_working_memory",
    }
    assert turn["background_signal_extraction"]["model"] == (
        "gemini/gemini-2.5-flash-lite"
    )
    assert turn["llm_usage_summary"]["total_tokens"] == base_tokens + 45
    assert turn["llm_usage_summary"]["llm_call_count"] == (
        len(turn["llm_calls"]) + 2
    )
    assert turn["llm_usage_summary"]["missing_usage_call_count"] == 0


