def test_active_working_memory_evidence_includes_compact_service_observation_refs():
    evidence = build_active_working_memory_evidence(
        current_memory=ActiveWorkingMemory.from_text("Customer needs installation near Cavite."),
        latest_user_message="sa gen tri sana",
        assistant_response="JOEM TIRE CENTER - General Trias, Cavite",
        tool_results=[
            {
                "name": "find_installation_partners",
                "result": {
                    "status": "ok",
                    "observation_ref": "svc_obs_installation_partners_1",
                    "presentation_ref": "pres_installation_partners_test",
                    "query_basis": {
                        "location": "gen tri",
                        "customer_location_label": "General Trias, Cavite",
                        "service_type": "installation",
                    },
                    "coverage_assessment": {
                        "installation_service_area_status": "has_installation_partner_options",
                    },
                    "installation_partner_card_headers": [
                        {
                            "name": "JOEM TIRE CENTER (ARNALDO HI-WAY)",
                            "municipality_city": "General Trias, Cavite",
                        }
                    ],
                },
            }
        ],
        recent_turns=[],
    )

    summary = evidence["assistant_response_summary"]
    latest_service = evidence["latest_service_observation"]
    assert "svc_obs_installation_partners_1" in summary
    assert "General Trias, Cavite" in summary
    assert "not booking" in summary
    assert latest_service["query_basis"]["customer_location_label"] == "General Trias, Cavite"
    assert latest_service["coverage_status"] == "has_installation_partner_options"
    assert latest_service["card_count"] == 1
    assert "JOEM TIRE CENTER" not in str(latest_service["query_basis"])


