def test_promo_fact_audit_context_does_not_promote_category_choices_to_promos():
    context = _promo_fact_audit_context(
        [
            {
                "name": "search_promo_catalog",
                "full_result": {
                    "status": "ok",
                    "evidence_ref": "promo_search:test:scope",
                    "tire_size": "185/65R15",
                    "requested_brands": ["Requested catalog brand"],
                    "matched_requested_brands": [],
                    "unmatched_requested_brands": [
                        "Requested catalog brand"
                    ],
                    "allowed_promo_refs": [],
                    "candidates": [],
                },
            },
            {
                "name": "discover_brand_buckets",
                "full_result": {
                    "status": "ok",
                    "presentation_ref": "price_categories_test",
                    "bucket_cards": [
                        {"bucket": "mid_range", "label": "Mid Range"}
                    ],
                },
            },
        ]
    )

    search = context["promo_searches"][0]
    category = context["category_choice_surfaces"][0]

    assert search["provider_available"] is True
    assert search["applicable_promo_refs"] == []
    assert search["unmatched_requested_brands"] == [
        "Requested catalog brand"
    ]
    assert search["reviewed_search_scope_outcome"] == (
        "no_verified_applicable_promo_returned"
    )
    assert "exact reviewed search scope" in search["search_scope_boundary"]
    assert context["verified_product_promos"] == []
    assert "does not prove any promo" in category[
        "authority_boundary"
    ]


def test_promo_response_contract_keeps_only_customer_claim_authority():
    context = _promo_fact_audit_context(
        [
            {
                "name": "search_promo_catalog",
                "full_result": {
                    "status": "ok",
                    "mode": "targeted",
                    "evidence_ref": "promo_search:test:scope",
                    "requested_brands": ["Example Brand"],
                    "allowed_promo_refs": ["promo:example"],
                    "candidates": [
                        {
                            "promo_ref": "promo:example",
                            "title": "Example Offer",
                            "brands": ["Example Brand"],
                            "offer_summary": "Buy 3 get 1 free.",
                            "relevant_mechanics": [
                                {"text": "Buy four eligible tires."}
                            ],
                            "retrieval_score": 0.998,
                            "vector_distance": 0.002,
                            "source_evidence": ["private:retrieval-row"],
                        }
                    ],
                },
            }
        ]
    )

    serialized = json.dumps(context)
    promo = context["promo_searches"][0]["applicable_promos"][0]

    assert context["version"] == "promo_response_contract_v1"
    assert context["answer_contract"]["requested_answer_scope"] == (
        "targeted_promo_answer"
    )
    assert promo["promo_ref"] == "promo:example"
    assert promo["relevant_mechanics"] == [
        "Buy four eligible tires."
    ]
    assert "retrieval_score" not in serialized
    assert "vector_distance" not in serialized
    assert "private:retrieval-row" not in serialized
